// Package addrset provides a set of blockchain addresses backed by a
// B+ tree, with a read-only view type for safe cross-realm exposure.
//
// It mirrors the gno.land/p/moul/addrset API on a
// gno.land/p/nt/bptree/v0 backing: a B+ tree packs many entries per
// persisted node, so a stored address costs ~0.9 KB vs the
// one-node-per-entry AVL backing's ~2.0 KB (2.2x asymptotically, 1.6x
// at 10 entries; insert gas ~2.1x less). Prefer this package when sets
// are part of persisted realm state; the omitted Tree() escape hatch is
// deliberate, so the backing store never leaks.
//
// Two behavioral differences from the AVL-backed moul package, both
// consequences of the in-place-mutating backing:
//
//   - the set must NOT be mutated (Add/Remove) from inside an iteration
//     callback — the AVL backing's copy-on-write tolerated it, this one
//     does not;
//   - do not copy a non-zero Set by value — the copies share live tree
//     nodes while their roots and sizes diverge (the AVL backing's
//     copies were independent snapshots).
//
// Example:
//
//	var set addrset.Set // the zero value is an empty, usable set
//
//	set.Add(addr)   // true (newly added)
//	set.Has(addr)   // true
//	set.Remove(addr) // true (was present)
package addrset

import "gno.land/p/nt/bptree/v0"

// Set stores a set of addresses in sorted order. The zero value is an
// empty, usable set.
type Set struct {
	tree bptree.BPTree
}

// Add inserts an address into the set.
// Returns true if the address was newly added, false if it already existed.
func (s *Set) Add(addr address) bool {
	return !s.tree.Set(string(addr), nil)
}

// Remove deletes an address from the set.
// Returns true if the address was found and removed, false if it didn't exist.
func (s *Set) Remove(addr address) bool {
	_, removed := s.tree.Remove(string(addr))
	return removed
}

// Has checks if an address exists in the set.
func (s *Set) Has(addr address) bool {
	return s.tree.Has(string(addr))
}

// Size returns the number of addresses in the set.
func (s *Set) Size() int {
	return s.tree.Size()
}

// IterateByOffset walks through addresses in sorted order, starting at
// the given offset and visiting up to count addresses. The callback
// returns true to stop iteration. The set must not be modified during
// iteration (no Add or Remove from the callback).
func (s *Set) IterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.IterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

// ReverseIterateByOffset walks through addresses in reverse (descending)
// order, starting at the given offset (counted from the end) and
// visiting up to count addresses. The callback returns true to stop
// iteration. The set must not be modified during iteration (no Add or
// Remove from the callback).
func (s *Set) ReverseIterateByOffset(offset int, count int, cb func(addr address) bool) {
	s.tree.ReverseIterateByOffset(offset, count, func(key string, _ any) bool {
		return cb(address(key))
	})
}

package addrset

// ReadonlySet is a read-only view of a *Set. Cross-package callers cannot
// mutate the underlying set through this type: it exposes no mutator
// methods and holds the *Set in an unexported field, so a foreign realm
// can neither reach the set nor invoke Add/Remove on it.
//
// A ReadonlySet is a thin handle over the live Set (it does not copy or
// snapshot), so reads through it always reflect the Set's current contents.
type ReadonlySet struct {
	set *Set
}

// NewReadonlySet returns a read-only view of s.
func NewReadonlySet(s *Set) *ReadonlySet {
	return &ReadonlySet{set: s}
}

// Readonly returns a read-only view of the set.
func (s *Set) Readonly() *ReadonlySet {
	return NewReadonlySet(s)
}

// Has reports whether addr is in the underlying set.
func (r ReadonlySet) Has(addr address) bool {
	return r.set.Has(addr)
}

// Size returns the number of addresses in the underlying set.
func (r ReadonlySet) Size() int {
	return r.set.Size()
}

// IterateByOffset walks the underlying set in sorted order, starting at
// offset and visiting up to count addresses. fn returns true to stop early;
// IterateByOffset returns true if iteration was stopped that way.
//
// The wrapped Set.IterateByOffset has no return value, so the "stopped"
// result is synthesized from the last callback return via a
// closure-captured local.
func (r ReadonlySet) IterateByOffset(offset, count int, fn func(addr address) bool) (stopped bool) {
	r.set.IterateByOffset(offset, count, func(a address) bool {
		stopped = fn(a)
		return stopped
	})
	return stopped
}

// ReverseIterateByOffset is IterateByOffset in reverse (descending) order.
func (r ReadonlySet) ReverseIterateByOffset(offset, count int, fn func(addr address) bool) (stopped bool) {
	r.set.ReverseIterateByOffset(offset, count, func(a address) bool {
		stopped = fn(a)
		return stopped
	})
	return stopped
}

package commondao

import (
	"errors"

	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/addrset"
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/bptree/v0/list"
	"gno.land/p/nt/seqid/v0"
)

// DefaultMaxActiveProposals is the default cap for simultaneously active
// proposals per DAO. Every active proposal stores a council snapshot, so
// the cap bounds storage. It is applied at construction; a hosting realm
// may override it per DAO via SetMaxActiveProposals (the reference realm
// keeps this default).
const DefaultMaxActiveProposals = 32

var (
	ErrCouncilUpdateOverlap  = errors.New("council update adds and removes the same address")
	ErrDAOIsDeleted          = errors.New("DAO is deleted")
	ErrEmptyCouncil          = errors.New("council update would remove every council member")
	ErrExecutionNotAllowed   = errors.New("proposal must be active or passed to be executed")
	ErrInvalidVoteChoice     = errors.New("invalid vote choice")
	ErrMaxActiveProposals    = errors.New("max number of active proposals reached")
	ErrMaxCapExemptProposals = errors.New("creator already has an active cap exempt proposal")
	ErrNotElectorateMember   = errors.New("account is not a member of the proposal's electorate")
	ErrOverflow              = errors.New("next ID overflows uint64")
	ErrProposalKindExists    = errors.New("proposal kind already registered")
	ErrProposalKindNotFound  = errors.New("proposal kind not found")
	ErrProposalKindRequired  = errors.New("proposal kind is required")
	ErrProposalNotFound      = errors.New("proposal not found")
	ErrVotingDeadlineNotMet  = errors.New("voting deadline not met")
	ErrVotingDeadlinePassed  = errors.New("voting deadline has passed")
	ErrWithdrawalNotAllowed  = errors.New("withdrawal not allowed for proposals with votes")
)

// CommonDAO defines a DAO.
//
// # Security
//
// A *CommonDAO is a mutable handle: its exported mutators (UpdateCouncil,
// Dissolve, Propose, Vote, Execute, Withdraw, SetTreasuryFrozen,
// SetMaxActiveProposals, RegisterKind, DeregisterKind) are meant for the
// realm that owns the DAO.
// Three rules apply at realm boundaries:
//
//  1. Do not ACCEPT a *CommonDAO from an external/untrusted caller.
//  2. Do not RETURN a *CommonDAO from any function callable by untrusted
//     realms — return dao.Readonly() (a ReadonlyCommonDAO view) instead.
//  3. Do not TRUST a readonly view received from an untrusted caller: it
//     is a live handle over the sender's data.
type CommonDAO struct {
	id                 uint64
	name               string
	description        string
	purpose            string
	addr               address // derived treasury address, empty when unset
	parent             *CommonDAO
	children           list.IList
	council            *addrset.Set
	genID              seqid.ID
	kinds              *bptree.BPTree // proposal kind name -> ProposalKind
	activeProposals    *proposalStorage
	finishedProposals  *proposalStorage
	deleted            bool // Soft delete
	treasuryFrozen     bool
	maxActiveProposals int
	proposing          bool // re-entrancy latch around a kind's New in Propose
	executing          bool // re-entrancy latch around Execute
}

// New creates a new common DAO.
func New(options ...Option) *CommonDAO {
	dao := &CommonDAO{
		children:           &list.List{},
		council:            &addrset.Set{},
		kinds:              bptree.NewBPTree32(),
		activeProposals:    newProposalStorage(),
		finishedProposals:  newProposalStorage(),
		maxActiveProposals: DefaultMaxActiveProposals,
	}
	for _, apply := range options {
		apply(dao)
	}
	return dao
}

// ID returns DAO's unique identifier.
func (dao CommonDAO) ID() uint64 {
	return dao.id
}

// Name returns DAO's name.
func (dao CommonDAO) Name() string {
	return dao.name
}

// Purpose returns the DAO's purpose. Together with the description it
// forms the DAO's Charter (docs/CONSTITUTION.md :1485).
func (dao CommonDAO) Purpose() string {
	return dao.purpose
}

// Description returns DAO's description.
func (dao CommonDAO) Description() string {
	return dao.description
}

// Address returns the DAO's treasury address, assigned at creation with
// WithAddress. The package never derives or uses the address itself:
// hosting realms derive it (e.g. from a realm sub-identity) and operate
// its funds through their own banker. Empty when unset.
func (dao CommonDAO) Address() address {
	return dao.addr
}

// IsTreasuryFrozen checks if the DAO's treasury is frozen. The package
// stores the flag only; hosting realms enforce it when moving funds.
func (dao CommonDAO) IsTreasuryFrozen() bool {
	return dao.treasuryFrozen
}

// SetTreasuryFrozen freezes or unfreezes the DAO's treasury.
func (dao *CommonDAO) SetTreasuryFrozen(frozen bool) {
	dao.treasuryFrozen = frozen
}

// Parent returns the parent DAO.
// Null can be returned when DAO has no parent assigned.
func (dao CommonDAO) Parent() *CommonDAO {
	return dao.parent
}

// ChildrenCount returns the number of direct children DAOs.
func (dao CommonDAO) ChildrenCount() int {
	return dao.children.Len()
}

// IterateChildren iterates the direct children DAOs.
func (dao CommonDAO) IterateChildren(fn func(*CommonDAO) bool) (stopped bool) {
	dao.children.ForEach(func(_ int, v any) bool {
		stopped = fn(v.(*CommonDAO))
		return stopped
	})
	return stopped
}

// Council returns a read only view of the DAO council.
//
// The council is the set of addresses entitled to vote. It changes only
// through UpdateCouncil (normally called by a council update proposal
// executor) or constructor options.
func (dao CommonDAO) Council() *addrset.ReadonlySet {
	return dao.council.Readonly()
}

// UpdateCouncil adds and removes council members as idempotent set
// operations: adding an existing member or removing an absent one is a
// no-op, so concurrently passed council updates merge deterministically in
// execution order, and a full council replacement in a single update is
// legal.
//
// The final set is (council ∪ add) \ remove. An update that adds and
// removes the same address is rejected, and an update whose final set
// would empty a non-empty council returns ErrEmptyCouncil: executors must
// propagate the error (failing the proposal) instead of panicking, which
// would revert the transaction and leave the proposal stuck.
func (dao *CommonDAO) UpdateCouncil(add, remove []address) error {
	for _, a := range add {
		for _, r := range remove {
			if a == r {
				return ErrCouncilUpdateOverlap
			}
		}
	}

	// The final set can only be empty when nothing is added: overlap is
	// rejected above, so any added address survives its own update.
	if dao.council.Size() > 0 && len(add) == 0 {
		empty := true
		dao.council.IterateByOffset(0, dao.council.Size(), func(member address) bool {
			for _, r := range remove {
				if r == member {
					return false // removed: keep looking for a survivor
				}
			}
			empty = false
			return true
		})
		if empty {
			return ErrEmptyCouncil
		}
	}

	for _, a := range add {
		dao.council.Add(a)
	}
	for _, r := range remove {
		dao.council.Remove(r)
	}
	return nil
}

// ActiveProposalsSize returns the number of active proposals, including
// early passed proposals that were not executed yet.
func (dao CommonDAO) ActiveProposalsSize() int {
	return dao.activeProposals.Size()
}

// IterateActiveProposals iterates active proposals ordered by ID.
func (dao CommonDAO) IterateActiveProposals(offset, count int, reverse bool, fn func(*Proposal) bool) bool {
	return dao.activeProposals.Iterate(offset, count, reverse, fn)
}

// FinishedProposalsSize returns the number of finished proposals.
func (dao CommonDAO) FinishedProposalsSize() int {
	return dao.finishedProposals.Size()
}

// IterateFinishedProposals iterates finished proposals ordered by ID.
func (dao CommonDAO) IterateFinishedProposals(offset, count int, reverse bool, fn func(*Proposal) bool) bool {
	return dao.finishedProposals.Iterate(offset, count, reverse, fn)
}

// IsDeleted returns true when DAO has been soft deleted.
func (dao CommonDAO) IsDeleted() bool {
	return dao.deleted
}

// MaxActiveProposals returns the cap for simultaneously active proposals.
func (dao CommonDAO) MaxActiveProposals() int {
	return dao.maxActiveProposals
}

// SetMaxActiveProposals changes the cap for simultaneously active
// proposals. Values below one are ignored: a DAO must always be able to
// propose.
func (dao *CommonDAO) SetMaxActiveProposals(max int) {
	if max >= 1 {
		dao.maxActiveProposals = max
	}
}

// RegisterKind registers a proposal kind by its name.
//
// Registered kinds are the only way to create proposals: Propose looks
// kinds up by name and calls their New factory, so a proposal type is
// proposable iff its kind is registered. Like SetTreasuryFrozen, this
// mutator is meant for the realm that owns the DAO (typically called at
// DAO creation and by governance proposal executors).
func (dao *CommonDAO) RegisterKind(k ProposalKind) error {
	if k == nil || k.Name() == "" {
		return ErrProposalKindRequired
	}
	if dao.kinds.Has(k.Name()) {
		return ErrProposalKindExists
	}
	dao.kinds.Set(k.Name(), k)
	return nil
}

// DeregisterKind removes a proposal kind by name.
//
// Deregistering only blocks new proposals: the registry is read at
// Propose time only, so in-flight proposals of the kind keep their
// frozen definition and still vote and execute.
//
// This is a plain registry primitive with no reserved names: any
// registered kind can be removed. A consuming realm that must keep a
// kind un-removable (e.g. a governance kind that manages the kind set)
// enforces that as its own policy, not through this package.
func (dao *CommonDAO) DeregisterKind(name string) error {
	if _, removed := dao.kinds.Remove(name); !removed {
		return ErrProposalKindNotFound
	}
	return nil
}

// HasKind checks if a proposal kind is registered.
func (dao CommonDAO) HasKind(name string) bool {
	return dao.kinds.Has(name)
}

// KindNames returns the names of the registered proposal kinds, sorted.
func (dao CommonDAO) KindNames() []string {
	names := make([]string, 0, dao.kinds.Size())
	dao.kinds.IterateByOffset(0, dao.kinds.Size(), func(name string, _ any) bool {
		names = append(names, name)
		return false
	})
	return names
}

// Propose creates a new DAO proposal.
//
// Proposals are created through registered proposal kinds: the kind is
// looked up by name in the DAO's registry and its New factory builds the
// proposal definition from args. The registry is read only here and the
// definition is frozen once the proposal is created, so deregistering a
// kind later never touches in-flight proposals.
//
// The proposal's electorate is the council snapshot taken now: members
// added later vote on the next proposal; members removed later remain in
// the electorate, where their silence counts against passage.
//
// The number of simultaneously active proposals is capped. Definitions
// implementing CapExempt (e.g. council updates, which must never be
// blockable by a full cap) are exempt but bounded to one active proposal
// per creator.
func (dao *CommonDAO) Propose(creator address, kind string, args any) (*Proposal, error) {
	if dao.deleted {
		return nil, ErrDAOIsDeleted
	}

	v := dao.kinds.Get(kind)
	if v == nil {
		return nil, ErrProposalKindNotFound
	}

	// Re-entrancy latch: a kind's New must not trigger another Propose on
	// this DAO (e.g. via a captured handle), which could nest factory
	// calls or grow active storage unboundedly before the first returns.
	if dao.proposing {
		panic("commondao: re-entrant Propose is not allowed")
	}
	dao.proposing = true
	// Deferred so a panicking New cannot leave the latch stuck (which would
	// brick every future Propose on this DAO for a consumer that recovers
	// the panic within the transaction); mirrors the executing latch.
	defer func() { dao.proposing = false }()
	d, err := v.(ProposalKind).New(dao.Readonly(), args)
	if err != nil {
		return nil, err
	}

	if d == nil {
		return nil, ErrProposalDefinitionRequired
	}

	if _, exempt := d.(CapExempt); exempt {
		var found bool
		dao.activeProposals.Iterate(0, dao.activeProposals.Size(), false, func(p *Proposal) bool {
			if _, ok := p.definition.(CapExempt); ok && p.creator == creator {
				found = true
				return true
			}
			return false
		})
		if found {
			return nil, ErrMaxCapExemptProposals
		}
	} else if dao.activeProposals.Size() >= dao.maxActiveProposals {
		return nil, ErrMaxActiveProposals
	}

	id, ok := dao.genID.TryNext()
	if !ok {
		return nil, ErrOverflow
	}

	p, err := newProposal(uint64(id), creator, d)
	if err != nil {
		return nil, err
	}

	// Snapshot the current council as the proposal's electorate
	dao.council.IterateByOffset(0, dao.council.Size(), func(member address) bool {
		p.electorate.Add(member)
		return false
	})

	dao.activeProposals.Add(p)
	return p, nil
}

// GetProposal returns a proposal or nil when proposal is not found.
func (dao CommonDAO) GetProposal(proposalID uint64) *Proposal {
	p := dao.activeProposals.Get(proposalID)
	if p != nil {
		return p
	}
	return dao.finishedProposals.Get(proposalID)
}

// Withdraw withdraws a proposal that has no votes.
// Only active proposals without votes can be withdrawn, and once
// withdrawn they are considered finished.
func (dao *CommonDAO) Withdraw(proposalID uint64) error {
	p := dao.activeProposals.Get(proposalID)
	if p == nil {
		return ErrProposalNotFound
	}

	if p.status != StatusActive {
		return ErrStatusIsNotActive
	}

	if p.record.Size() > 0 {
		return ErrWithdrawalNotAllowed
	}

	p.status = StatusWithdrawn
	dao.activeProposals.Remove(p.id)
	dao.finishedProposals.Add(p)
	return nil
}

// Vote submits a new vote for a proposal.
//
// Votes are only allowed to members of the proposal's electorate while the
// proposal is active and within the voting period. A member may change
// their vote by voting again.
//
// Proposals are re-evaluated after every recorded vote: a YES tally at
// the definition's threshold decides the proposal immediately, and a
// simple majority of NO dismisses it immediately.
func (dao *CommonDAO) Vote(member address, proposalID uint64, c VoteChoice, reason string) error {
	if dao.deleted {
		return ErrDAOIsDeleted
	}

	p := dao.activeProposals.Get(proposalID)
	if p == nil {
		return ErrProposalNotFound
	}

	if p.status != StatusActive {
		return ErrStatusIsNotActive
	}

	if !p.electorate.Has(member) {
		return ErrNotElectorateMember
	}

	if p.HasVotingDeadlinePassed() {
		return ErrVotingDeadlinePassed
	}

	if c != ChoiceYes && c != ChoiceNo && c != ChoiceAbstain {
		return ErrInvalidVoteChoice
	}

	p.record.AddVote(Vote{
		addr:   member,
		choice: c,
		reason: reason,
	})

	// Early termination: proposals are decided the moment the outcome is
	// mathematically settled. A passed proposal stays in the active
	// storage until executed; a dismissed one is finished.
	switch TallyDefault(p.record.Readonly(), p.Electorate(), p.definition.Threshold()) {
	case OutcomePassed:
		p.status = StatusPassed
	case OutcomeDismissed:
		dao.dismiss(p)
	}
	return nil
}

// Execute executes a proposal.
//
// Proposals that already passed (decided early by the default Council
// rules) execute immediately. Active proposals are tallied once their
// voting deadline passes and are dismissed unless passed.
//
// sub is the DAO-scoped sub-identity that the host mints and passes into
// the executor as its value-movement authority (see ExecFunc). The
// executor is non-crossing, so it is called directly. Execute itself is
// not a crossing function (sub sits in a non-first parameter slot)
// because /p/ production code cannot declare crossing functions.
func (dao *CommonDAO) Execute(proposalID uint64, sub realm) error {
	if dao.deleted {
		return ErrDAOIsDeleted
	}

	// Re-entrancy latch: an executor must not re-enter Execute on this
	// DAO. Remove-before-run already stops the same proposal from running
	// twice; this additionally blocks an executor from executing a
	// different proposal of the same DAO mid-execution.
	if dao.executing {
		panic("commondao: re-entrant Execute is not allowed")
	}
	dao.executing = true
	defer func() { dao.executing = false }()

	p := dao.activeProposals.Get(proposalID)
	if p == nil {
		return ErrProposalNotFound
	}

	switch p.status {
	case StatusPassed:
		// Decided early: execute now, before the voting deadline
	case StatusActive:
		if !p.HasVotingDeadlinePassed() {
			return ErrVotingDeadlineNotMet
		}
	default:
		return ErrExecutionNotAllowed
	}

	// The proposal leaves active storage before any definition code
	// (Validate, the executor) runs, so a re-entrant Execute call
	// cannot run it twice.
	dao.activeProposals.Remove(p.id)

	// Tally proposals that are still active after their deadline;
	// undecided proposals are dismissed. Vote already decides settled
	// outcomes, so this re-tally only matters for definitions whose
	// Threshold is not constant.
	if p.status == StatusActive {
		if TallyDefault(p.record.Readonly(), p.Electorate(), p.definition.Threshold()) == OutcomePassed {
			p.status = StatusPassed
		} else {
			p.status = StatusDismissed
			dao.finishedProposals.Add(p)
			return nil
		}
	}

	// IMPORTANT, from this point on, any error is going to result
	// in a proposal failure and execute will succeed.

	// Validate the passed proposal before execution
	err := p.Validate()

	// Execute proposal only if it's executable
	if err == nil {
		if e, ok := p.Definition().(Executable); ok {
			if fn := e.Executor(); fn != nil {
				err = fn(0, sub)
			}
		}
	}

	// Proposal fails if there is any error during validation and execution process
	if err != nil {
		p.status = StatusFailed
		p.statusReason = err.Error()
	} else {
		p.status = StatusExecuted
		p.statusReason = ""
	}

	// Whichever the outcome of the validation, tallying
	// and execution consider the proposal finished.
	dao.finishedProposals.Add(p)
	return nil
}

// dismiss finishes a proposal as dismissed.
func (dao *CommonDAO) dismiss(p *Proposal) {
	p.status = StatusDismissed
	dao.activeProposals.Remove(p.id)
	dao.finishedProposals.Add(p)
}

// Dissolve soft deletes the DAO after dismissing every in-flight proposal
// (both still-active and passed-but-unexecuted ones). Dissolution is
// terminal: a deleted DAO rejects proposals, votes and executions, so
// nothing may remain pending.
func (dao *CommonDAO) Dissolve(reason string) {
	var pending []*Proposal
	dao.activeProposals.Iterate(0, dao.activeProposals.Size(), false, func(p *Proposal) bool {
		pending = append(pending, p)
		return false
	})

	for _, p := range pending {
		p.statusReason = reason
		dao.dismiss(p)
	}
	dao.deleted = true
}

package commondao

// Option configures the CommonDAO.
type Option func(*CommonDAO)

// WithID assigns a unique identifier to the DAO.
func WithID(id uint64) Option {
	return func(dao *CommonDAO) {
		dao.id = id
	}
}

// WithName assigns a name to the DAO.
func WithName(name string) Option {
	return func(dao *CommonDAO) {
		dao.name = name
	}
}

// WithPurpose assigns a purpose to the DAO. Purpose and description
// together form the DAO's Charter (docs/CONSTITUTION.md :1485).
func WithPurpose(purpose string) Option {
	return func(dao *CommonDAO) {
		dao.purpose = purpose
	}
}

// WithDescription assigns a description to the DAO.
func WithDescription(description string) Option {
	return func(dao *CommonDAO) {
		dao.description = description
	}
}

// WithAddress assigns a treasury address to the DAO. Hosting realms
// derive it, typically as a realm sub-identity address
// (chain.DerivePkgSubAddr) so each DAO owns a distinct account.
func WithAddress(addr address) Option {
	return func(dao *CommonDAO) {
		dao.addr = addr
	}
}

// WithParent assigns a parent DAO and registers the DAO as one of the
// parent's children, keeping both sides of the tree wired in one step.
func WithParent(p *CommonDAO) Option {
	return func(dao *CommonDAO) {
		dao.parent = p
		if p != nil {
			p.children.Append(dao)
		}
	}
}

// WithCouncilMember assigns a council member to the DAO.
func WithCouncilMember(addr address) Option {
	return func(dao *CommonDAO) {
		dao.council.Add(addr)
	}
}

// WithProposalKind registers a proposal kind on the DAO.
// It panics when the kind is nil, has an empty name, or its name is
// already registered.
//
// The package ships one concrete kind, ExecutionKind; seed it with
// WithProposalKind(ExecutionKind{}).
func WithProposalKind(k ProposalKind) Option {
	return func(dao *CommonDAO) {
		if err := dao.RegisterKind(k); err != nil {
			panic(err)
		}
	}
}

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// A fully audited version will be published as a subsequent release.
// Use in production at your own risk.
//
// Package commondao provides governance primitives following the Common
// DAO Spec (docs/CONSTITUTION.md, Appendix): a CommonDAO is a Council (a
// set of addresses with equal voting power), a proposal lifecycle decided
// by the constitution's default voting rules, and an optional sub-DAO
// tree.
//
// Proposal types are registered per DAO: a ProposalKind couples a
// registry name with a definition factory New(dao ReadonlyCommonDAO,
// args), and Propose(creator, kind, args) accepts exactly the kinds
// registered on the DAO. New receives only a readonly view, so it cannot
// mutate the DAO before the vote; a kind that must mutate state on
// execution captures its target *CommonDAO from args (populated only by
// trusted callers) and mutates in its executor. RegisterKind /
// DeregisterKind / HasKind / KindNames and the WithProposalKind option
// are the registry primitives; the package ships one concrete kind,
// ExecutionKind (arbitrary execution), and no governance meta-kinds —
// managing a DAO's kind set through governance is the consuming realm's
// job.
//
// Proposals snapshot the council as their electorate at creation and
// are decided the moment the outcome is mathematically settled: with
// integer math over D = |electorate| - abstains, a supermajority
// (3*yes >= 2*D) passes, a NO majority (2*no > D) dismisses, and
// proposals still undecided at their voting deadline are dismissed.
//
// A DAO may carry a treasury address and frozen flag; the package only
// stores them - hosting realms derive the address and move the funds.
//
// A *CommonDAO is a mutable handle for the realm that owns it: never
// accept one from, or return one to, an untrusted realm - readonly views
// (CommonDAO.Readonly) are the only safe handles to cross a realm
// boundary. See the package README for details.
//
// # Extending commondao in your own realm
//
// This package is mostly mechanism: it ships the ExecutionKind concrete kind
// (with a default voting policy) and the registry primitives, and leaves the
// rest of governance policy — which kinds a DAO accepts, how it manages them,
// and any per-kind constraints such as a treasury freeze — to the consuming
// realm. To add a proposal type of your own:
//
//   - Author a ProposalKind: a type with Name() string and
//     New(dao ReadonlyCommonDAO, args any) (ProposalDefinition, error). Make
//     the definition Executable (Executor() returns an ExecFunc) if it
//     mutates state on approval. If its executor moves funds from a DAO other
//     than the proposal's host, have the HOST realm consume a Funded-style
//     contract (FundingDAOID() uint64) — minting a DAO sub needs the host's
//     cur, so this contract is host-consumed, not package-dispatched; define
//     it in your realm, as the reference realm does.
//   - Apply your own policy. ExecutionKind runs the closure as-is (no check
//     beyond a non-nil Fn), so if your realm has treasury constraints (e.g. a
//     freeze flag) do NOT catalog ExecutionKind directly: author your own
//     execution kind whose definition wraps the closure with a Validable
//     check (Validate() error) enforcing those constraints, so arbitrary
//     execution cannot bypass them. The reference realm does this so a frozen
//     DAO cannot drain its own treasury through an execution proposal.
//   - Seed it. The owning realm holds the DAO handle, so no proposal is
//     needed: pass commondao.New(WithProposalKind(YourKind{}), …) at
//     construction, or call dao.RegisterKind(YourKind{}) directly.
//   - Author a typed, CLI-friendly wrapper
//     CreateYourProposal(cur realm, daoID uint64, …params…): council-gate the
//     caller, build the args struct, and call Propose. This is the only
//     public entry, so the args-capture trust boundary holds.
//   - Optionally add a runtime governance toggle. If the council should
//     register/deregister kinds by vote (rather than only at construction),
//     author a manage-kinds-style ProposalKind whose executor calls
//     RegisterKind/DeregisterKind, and keep that managing kind itself
//     un-deregisterable so the DAO can always recover.
//
// Trust boundary: New receives only a ReadonlyCommonDAO, so a kind — even an
// externally authored one — cannot mutate the host at Propose time. The
// mutable *CommonDAO reaches a definition only through args, which your
// trusted wrapper populates (an external proposer cannot obtain one). On
// execution the host passes the DAO's terminal, RealmSend-only sub, so a
// fund-moving executor is bounded to that one DAO address. See the reference
// realm gno.land/r/nt/commondao/v0 for a full worked example.
package commondao

package commondao

import (
	"errors"
	"time"
)

// executionKindName is the name of the arbitrary-execution kind.
const executionKindName = "execution"

var ErrExecutionFuncRequired = errors.New("execution proposal requires a non-nil Fn")

// defaultExecutionVotingPeriod is the voting period of execution proposals.
const defaultExecutionVotingPeriod = 7 * 24 * time.Hour

// ExecutionArgs are the args for the execution kind (ExecutionKind): a
// title, a body, and the ExecFunc to run on approval. The closure must be
// authored in a persistent realm so it survives Propose→Execute; a
// closure created by a `maketx run` script does not persist and cannot be
// executed later.
type ExecutionArgs struct {
	Title string
	Body  string
	Fn    ExecFunc
}

// ExecutionKind is the package's one concrete proposal kind: a stateless,
// reusable arbitrary-execution kind that runs an ExecFunc supplied by the
// proposer on approval. It is /p/-typed so any realm can register it with
// WithProposalKind(ExecutionKind{}) or RegisterKind without defining its
// own execution kind.
//
// The executor moves value only through the DAO-scoped sub the host
// passes (see ExecFunc): the host mints and passes that sub, so the
// executor receives whichever DAO's sub the host decides (its own DAO's by
// default). The closure is frozen at Propose (vote-integrity: the exact
// code is fixed before the vote).
//
// This kind applies NO policy check to the closure beyond a non-nil Fn: it
// runs the arbitrary code as-is. A realm that has treasury constraints (e.g.
// a freeze flag) should NOT catalog this kind directly; instead it should
// author its own execution kind whose definition wraps the closure with a
// Validable check that enforces those constraints (blocking execution while
// frozen, etc.), so arbitrary execution cannot bypass them. The reference
// realm gno.land/r/nt/commondao/v0 does exactly this.
type ExecutionKind struct{}

// Name returns the execution kind's registry name.
func (ExecutionKind) Name() string { return executionKindName }

// New validates ExecutionArgs and builds an execution definition. It is a
// pure factory: it receives only a readonly view and captures no mutable
// handle.
func (ExecutionKind) New(_ ReadonlyCommonDAO, args any) (ProposalDefinition, error) {
	a, ok := args.(ExecutionArgs)
	if !ok || a.Fn == nil {
		return nil, ErrExecutionFuncRequired
	}
	return executionDef{title: a.Title, body: a.Body, fn: a.Fn}, nil
}

// executionDef is the definition produced by ExecutionKind.
type executionDef struct {
	title string
	body  string
	fn    ExecFunc
}

func (d executionDef) Title() string             { return d.title }
func (d executionDef) Body() string              { return d.body }
func (executionDef) VotingPeriod() time.Duration { return defaultExecutionVotingPeriod }
func (executionDef) Threshold() Threshold        { return ThresholdSupermajority }
func (d executionDef) Executor() ExecFunc        { return d.fn }

package commondao

import (
	"errors"
	"time"

	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/addrset"
)

const (
	StatusActive    ProposalStatus = "active"
	StatusPassed    ProposalStatus = "passed"
	StatusDismissed ProposalStatus = "dismissed"
	StatusExecuted  ProposalStatus = "executed"
	StatusFailed    ProposalStatus = "failed"
	StatusWithdrawn ProposalStatus = "withdrawn"
)

// Vote choices, fixed by the Common DAO Spec's default voting rules.
const (
	ChoiceYes     VoteChoice = "YES"
	ChoiceNo      VoteChoice = "NO"
	ChoiceAbstain VoteChoice = "ABSTAIN"
)

// Thresholds for the constitution's default Council voting rules.
const (
	// ThresholdSupermajority passes with "two thirds or more" of the
	// tally denominator. The default for Council decisions.
	ThresholdSupermajority Threshold = iota

	// ThresholdSimpleMajority passes with "more than half" of the
	// tally denominator. The Constitution assigns it to specific
	// decisions, e.g. sub-DAO creation.
	ThresholdSimpleMajority
)

// Outcomes of tallying a proposal under the default Council rules.
const (
	OutcomePending Outcome = iota
	OutcomePassed
	OutcomeDismissed
)

var (
	ErrInvalidCreatorAddress      = errors.New("invalid proposal creator address")
	ErrInvalidVoterAddress        = errors.New("invalid voter address")
	ErrProposalDefinitionRequired = errors.New("proposal definition is required")
	ErrStatusIsNotActive          = errors.New("proposal status is not active")
)

type (
	// ProposalStatus defines a type for different proposal states.
	ProposalStatus string

	// VoteChoice defines a type for proposal vote choices.
	VoteChoice string

	// Threshold defines a type for the default tally thresholds.
	Threshold int

	// Outcome defines a type for default tally outcomes.
	Outcome int

	// ExecFunc defines a type for functions that execute proposals.
	//
	// The leading int makes ExecFunc non-crossing: the host calls it
	// directly (no cross), so the executor holds no realm cur of its own —
	// only the realm argument, a DAO-scoped sub-identity the host mints and
	// passes. Fund-moving executors send through that sub (e.g. banker
	// RealmSend), which is terminal and bounded to one DAO address;
	// executors that move no funds ignore it. The int is unused.
	//
	// Authority note: the sub is a least-authority DEFAULT, not a sandbox.
	// An executor is trusted realm code; because the sub is the executor's
	// only current realm value, it could regain the host realm's primary
	// authority via an explicit cross(sub) into a crossing function. That is
	// a visible, auditable call the reference realm's executors never make,
	// so their blast radius is one treasury — but a realm that runs
	// untrusted or user-registered executors gets no such guarantee. See ADR
	// pr6012_commondao_exec_scope.
	//
	// The sharper hazard for such a realm is not cross(sub) but the banker:
	// an executor can mint banker.NewBanker(BankerTypeRealmSend, sub) and
	// simply RETAIN it. Authorization happens at construction only, and the
	// banker holds no realm reference, so it persists across transactions
	// even though the sub itself cannot — a permanent, unrevocable
	// capability over that DAO's address, spendable later with no proposal.
	// It also bypasses any check the host performs before spending (a
	// frozen flag, a pause switch), because it reaches the bank keeper
	// without re-entering host code. Passing the sub to an executor whose
	// code the DAO has not vetted is therefore an irrevocable grant of that
	// DAO's treasury, not a scoped loan of it.
	ExecFunc func(int, realm) error

	// Proposal defines a DAO proposal.
	Proposal struct {
		id             uint64
		status         ProposalStatus
		definition     ProposalDefinition
		creator        address
		record         *VotingRecord
		electorate     *addrset.Set // council snapshot taken at Propose
		statusReason   string
		votingDeadline time.Time
		createdAt      time.Time
	}

	// ProposalDefinition defines an interface for custom proposal definitions.
	// These definitions define proposal content and behavior, essentially
	// allowing the definition of different proposal types.
	ProposalDefinition interface {
		// Title returns the proposal title.
		Title() string

		// Body returns proposal's body.
		// It usually contains description or values that are specific to the proposal,
		// like a description of the proposal's motivation or the list of values that
		// would be applied when the proposal is approved.
		Body() string

		// VotingPeriod returns the period where votes are allowed after proposal creation.
		// It is used to calculate the voting deadline from the proposal's creation date.
		VotingPeriod() time.Duration

		// Threshold returns the tally threshold for passing the proposal.
		// Proposals are decided by the constitution's default Council voting
		// rules: re-evaluated after every recorded vote, they can pass or be
		// dismissed before their voting deadline.
		//
		// Threshold is read on every Vote (for early passage) AND again in
		// the post-deadline re-tally inside Execute. Return a CONSTANT value:
		// a threshold that loosens over a proposal's lifetime can let the
		// deadline re-tally pass with fewer YES votes than voters faced when
		// they cast under the stricter earlier value. A changing threshold is
		// honored, but the definition author owns that consequence.
		Threshold() Threshold
	}

	// ProposalKind defines an interface for proposal kinds: named factories
	// for proposal definitions, registered per DAO. A kind is both the
	// registry key (Name) and the factory (New) for one proposal type, and
	// a DAO accepts proposals of exactly the kinds registered on it
	// (CommonDAO.RegisterKind).
	ProposalKind interface {
		// Name returns the kind name used as registry key, e.g. "treasury-spend".
		Name() string

		// New validates args and builds the proposal definition. Propose
		// passes a ReadonlyCommonDAO view of the host DAO, so New is a
		// pure factory that cannot mutate the host or its tree before the
		// vote; proposal targets and parameters come via args. A kind that
		// must mutate state on execution receives the target *CommonDAO
		// through args (which only trusted callers can populate), captures
		// it, and mutates in its Executor. The returned definition's
		// instance data is frozen at Propose like any proposal definition.
		New(dao ReadonlyCommonDAO, args any) (ProposalDefinition, error)
	}

	// CapExempt defines an interface for proposal definitions that are not
	// counted against the DAO's active proposals cap. Exempt definitions are
	// instead bounded to one active proposal per creator, so that proposals
	// which remove members (and therefore must never be blockable by a full
	// cap) stay bounded.
	CapExempt interface {
		// CapExempt marks the definition as exempt.
		CapExempt()
	}

	// Validable defines an interface for proposal definitions that require state validation.
	// Validation is done before execution and normally also during proposal rendering.
	Validable interface {
		// Validate validates that the proposal is valid for the current state.
		Validate() error
	}

	// Executable defines an interface for proposal definitions that modify state on approval.
	// Once proposals are executed they are archived and considered finished.
	Executable interface {
		// Executor returns a function to execute the proposal.
		Executor() ExecFunc
	}
)

// newProposal creates a new DAO proposal.
//
// The proposal is created with an empty electorate; Propose populates it
// with the council snapshot.
func newProposal(id uint64, creator address, d ProposalDefinition) (*Proposal, error) {
	if !creator.IsValid() {
		return nil, ErrInvalidCreatorAddress
	}

	now := time.Now()
	return &Proposal{
		id:             id,
		status:         StatusActive,
		definition:     d,
		creator:        creator,
		record:         &VotingRecord{},
		electorate:     &addrset.Set{},
		votingDeadline: now.Add(d.VotingPeriod()),
		createdAt:      now,
	}, nil
}

// ID returns the unique proposal identifier.
func (p Proposal) ID() uint64 {
	return p.id
}

// Definition returns the proposal definition.
// Proposal definitions define proposal content and behavior.
func (p Proposal) Definition() ProposalDefinition {
	return p.definition
}

// Status returns the current proposal status.
func (p Proposal) Status() ProposalStatus {
	return p.status
}

// Creator returns the address of the account that created the proposal.
func (p Proposal) Creator() address {
	return p.creator
}

// CreatedAt returns the time that proposal was created.
func (p Proposal) CreatedAt() time.Time {
	return p.createdAt
}

// VotingRecord returns a read only record with the votes submitted for
// the proposal. Votes are recorded through CommonDAO.Vote only.
func (p Proposal) VotingRecord() ReadonlyVotingRecord {
	return p.record.Readonly()
}

// Electorate returns the proposal's electorate: a read only view of the
// council snapshot taken when the proposal was created. Members added to
// the council afterwards vote on the next proposal; members removed or
// resigned afterwards remain in the electorate (their silence counts
// against passage).
func (p Proposal) Electorate() *addrset.ReadonlySet {
	return p.electorate.Readonly()
}

// StatusReason returns an optional reason that led to the current proposal status.
// Reason is mostly useful when a proposal fails.
func (p Proposal) StatusReason() string {
	return p.statusReason
}

// VotingDeadline returns the deadline after which no more votes should be allowed.
func (p Proposal) VotingDeadline() time.Time {
	return p.votingDeadline
}

// HasVotingDeadlinePassed checks if the voting deadline has been met.
func (p Proposal) HasVotingDeadlinePassed() bool {
	return !time.Now().Before(p.VotingDeadline())
}

// Validate validates that a proposal is valid for the current state.
// Validation is done when the proposal can still be executed (status is
// active or passed) and when the definition supports validation.
func (p Proposal) Validate() error {
	if p.status != StatusActive && p.status != StatusPassed {
		return nil
	}

	if v, ok := p.definition.(Validable); ok {
		return v.Validate()
	}
	return nil
}

// ExpectedOutcome returns the outcome the proposal would have if it were
// decided with the votes submitted so far. Useful for rendering.
func (p Proposal) ExpectedOutcome() Outcome {
	return TallyDefault(p.record.Readonly(), p.Electorate(), p.definition.Threshold())
}

package commondao

import (
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/seqid/v0"
)

// newProposalStorage creates a new proposal storage.
func newProposalStorage() *proposalStorage {
	return &proposalStorage{bptree.NewBPTree32()}
}

// proposalStorage stores proposals indexed by ID.
type proposalStorage struct {
	storage *bptree.BPTree // string(proposal ID) -> *Proposal
}

// Get returns a proposal or nil when proposal doesn't exist.
func (s proposalStorage) Get(id uint64) *Proposal {
	if v := s.storage.Get(makeProposalKey(id)); v != nil {
		return v.(*Proposal)
	}
	return nil
}

// Add adds a proposal to the storage.
func (s *proposalStorage) Add(p *Proposal) {
	if p == nil {
		return
	}

	s.storage.Set(makeProposalKey(p.ID()), p)
}

// Remove removes a proposal from the storage.
func (s *proposalStorage) Remove(id uint64) {
	s.storage.Remove(makeProposalKey(id))
}

// Size returns the number of proposals that the storage contains.
func (s proposalStorage) Size() int {
	return s.storage.Size()
}

// Iterate iterates proposals.
func (s proposalStorage) Iterate(offset, count int, reverse bool, fn func(*Proposal) bool) bool {
	cb := func(_ string, v any) bool { return fn(v.(*Proposal)) }

	if reverse {
		return s.storage.ReverseIterateByOffset(offset, count, cb)
	}
	return s.storage.IterateByOffset(offset, count, cb)
}

func makeProposalKey(id uint64) string {
	return seqid.ID(id).String()
}

package commondao

import (
	"time"

	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/addrset"
)

// ReadonlyCommonDAO is a read only view of a CommonDAO. It exposes only
// read side methods, holds the *CommonDAO in an unexported field, and every
// reachable value is itself readonly or a copy — so cross-realm holders
// cannot mutate the DAO through it. Views are live handles, not snapshots.
//
// This is the only safe handle to a DAO across a realm boundary: hosting
// realms must never return the *CommonDAO itself.
type ReadonlyCommonDAO struct {
	dao *CommonDAO
}

// Readonly returns a read only view of the DAO.
func (dao *CommonDAO) Readonly() ReadonlyCommonDAO {
	return ReadonlyCommonDAO{dao}
}

// ID returns DAO's unique identifier.
func (r ReadonlyCommonDAO) ID() uint64 {
	return r.dao.id
}

// Name returns DAO's name.
func (r ReadonlyCommonDAO) Name() string {
	return r.dao.name
}

// Purpose returns DAO's purpose (part of the Charter).
func (r ReadonlyCommonDAO) Purpose() string {
	return r.dao.purpose
}

// Description returns DAO's description.
func (r ReadonlyCommonDAO) Description() string {
	return r.dao.description
}

// Address returns the DAO's treasury address, or empty when unset.
func (r ReadonlyCommonDAO) Address() address {
	return r.dao.addr
}

// IsDeleted returns true when DAO has been soft deleted.
func (r ReadonlyCommonDAO) IsDeleted() bool {
	return r.dao.deleted
}

// IsTreasuryFrozen checks if the DAO's treasury is frozen.
func (r ReadonlyCommonDAO) IsTreasuryFrozen() bool {
	return r.dao.treasuryFrozen
}

// Council returns a read only view of the DAO council.
func (r ReadonlyCommonDAO) Council() *addrset.ReadonlySet {
	return r.dao.council.Readonly()
}

// HasKind checks if a proposal kind is registered on the DAO.
func (r ReadonlyCommonDAO) HasKind(name string) bool {
	return r.dao.HasKind(name)
}

// KindNames returns the names of the registered proposal kinds, sorted.
func (r ReadonlyCommonDAO) KindNames() []string {
	return r.dao.KindNames()
}

// Parent returns a read only view of the parent DAO when there is one.
func (r ReadonlyCommonDAO) Parent() (_ ReadonlyCommonDAO, found bool) {
	if r.dao.parent == nil {
		return ReadonlyCommonDAO{}, false
	}
	return r.dao.parent.Readonly(), true
}

// ChildrenCount returns the number of direct children DAOs.
func (r ReadonlyCommonDAO) ChildrenCount() int {
	return r.dao.children.Len()
}

// IterateChildren iterates the direct children DAOs.
// The callback can return true to stop iteration.
func (r ReadonlyCommonDAO) IterateChildren(fn func(ReadonlyCommonDAO) bool) (stopped bool) {
	r.dao.children.ForEach(func(_ int, v any) bool {
		stopped = fn(v.(*CommonDAO).Readonly())
		return stopped
	})
	return stopped
}

// GetProposal returns a read only view of a proposal when it exists.
func (r ReadonlyCommonDAO) GetProposal(proposalID uint64) (_ ReadonlyProposal, found bool) {
	p := r.dao.GetProposal(proposalID)
	if p == nil {
		return ReadonlyProposal{}, false
	}
	return p.Readonly(), true
}

// ActiveProposalsSize returns the number of active proposals.
func (r ReadonlyCommonDAO) ActiveProposalsSize() int {
	return r.dao.activeProposals.Size()
}

// FinishedProposalsSize returns the number of finished proposals.
func (r ReadonlyCommonDAO) FinishedProposalsSize() int {
	return r.dao.finishedProposals.Size()
}

// IterateActiveProposals iterates read only views of the active proposals.
// The callback can return true to stop iteration.
func (r ReadonlyCommonDAO) IterateActiveProposals(offset, count int, reverse bool, fn func(ReadonlyProposal) bool) bool {
	return r.dao.activeProposals.Iterate(offset, count, reverse, func(p *Proposal) bool {
		return fn(p.Readonly())
	})
}

// IterateFinishedProposals iterates read only views of the finished proposals.
// The callback can return true to stop iteration.
func (r ReadonlyCommonDAO) IterateFinishedProposals(offset, count int, reverse bool, fn func(ReadonlyProposal) bool) bool {
	return r.dao.finishedProposals.Iterate(offset, count, reverse, func(p *Proposal) bool {
		return fn(p.Readonly())
	})
}

// ReadonlyProposal is a read only view of a Proposal. Proposal content is
// exposed flattened (Title, Body): the view never exposes the underlying
// ProposalDefinition, whose Executor would otherwise be callable by any
// holder with the hosting realm's authority.
type ReadonlyProposal struct {
	p *Proposal
}

// Readonly returns a read only view of the proposal.
func (p *Proposal) Readonly() ReadonlyProposal {
	return ReadonlyProposal{p}
}

// ID returns the unique proposal identifier.
func (r ReadonlyProposal) ID() uint64 {
	return r.p.id
}

// Status returns the current proposal status.
func (r ReadonlyProposal) Status() ProposalStatus {
	return r.p.status
}

// StatusReason returns an optional reason that led to the current proposal status.
func (r ReadonlyProposal) StatusReason() string {
	return r.p.statusReason
}

// Creator returns the address of the account that created the proposal.
func (r ReadonlyProposal) Creator() address {
	return r.p.creator
}

// CreatedAt returns the time that proposal was created.
func (r ReadonlyProposal) CreatedAt() time.Time {
	return r.p.createdAt
}

// VotingDeadline returns the deadline after which no more votes are allowed.
func (r ReadonlyProposal) VotingDeadline() time.Time {
	return r.p.votingDeadline
}

// Title returns the proposal definition's title.
func (r ReadonlyProposal) Title() string {
	return r.p.definition.Title()
}

// Body returns the proposal definition's body.
func (r ReadonlyProposal) Body() string {
	return r.p.definition.Body()
}

// VotingRecord returns a read only record with the submitted votes.
func (r ReadonlyProposal) VotingRecord() ReadonlyVotingRecord {
	return r.p.record.Readonly()
}

// Electorate returns a read only view of the proposal's electorate.
func (r ReadonlyProposal) Electorate() *addrset.ReadonlySet {
	return r.p.Electorate()
}

package commondao

import (
	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/addrset"
	"gno.land/p/nt/bptree/v0"
)

type (
	// VoteIterFn defines a callback to iterate votes.
	VoteIterFn func(Vote) (stop bool)

	// VotesCountIterFn defines a callback to iterate voted choices.
	VotesCountIterFn func(_ VoteChoice, voteCount int) (stop bool)

	// Vote defines a single vote. Its fields are unexported so instances
	// cannot be forged or reshaped outside the package: votes enter a
	// record only through CommonDAO.Vote's gates.
	Vote struct {
		addr   address
		choice VoteChoice
		reason string
	}
)

// NewVote creates a vote, validating the address and choice. It exists
// so external code can build records to independently re-verify a tally
// with TallyDefault; votes reach a DAO's own records only through
// CommonDAO.Vote.
func NewVote(addr address, choice VoteChoice, reason string) (Vote, error) {
	if !addr.IsValid() {
		return Vote{}, ErrInvalidVoterAddress
	}

	if choice != ChoiceYes && choice != ChoiceNo && choice != ChoiceAbstain {
		return Vote{}, ErrInvalidVoteChoice
	}

	return Vote{addr: addr, choice: choice, reason: reason}, nil
}

// Address returns the address of the account that submitted the vote.
func (v Vote) Address() address {
	return v.addr
}

// Choice returns the voted choice.
func (v Vote) Choice() VoteChoice {
	return v.choice
}

// Reason returns the optional reason for the vote.
func (v Vote) Reason() string {
	return v.reason
}

// ReadonlyVotingRecord defines a read only voting record. The copy
// captures the live record's tree roots by value, so a held value can go
// stale in surprising ways: fetch it, read it, and re-fetch rather than
// holding it across votes.
type ReadonlyVotingRecord struct {
	votes bptree.BPTree // string(address) -> Vote
	count bptree.BPTree // string(choice) -> int
}

// Size returns the total number of votes that record contains.
func (r ReadonlyVotingRecord) Size() int {
	return r.votes.Size()
}

// Iterate iterates voting record votes.
func (r ReadonlyVotingRecord) Iterate(offset, count int, reverse bool, fn VoteIterFn) bool {
	cb := func(_ string, v any) bool { return fn(v.(Vote)) }
	if reverse {
		return r.votes.ReverseIterateByOffset(offset, count, cb)
	}
	return r.votes.IterateByOffset(offset, count, cb)
}

// IterateVotesCount iterates voted choices with the amount of votes submitted for each.
func (r ReadonlyVotingRecord) IterateVotesCount(fn VotesCountIterFn) bool {
	return r.count.Iterate("", "", func(k string, v any) bool {
		return fn(VoteChoice(k), v.(int))
	})
}

// VoteCount returns the number of votes for a single voting choice.
func (r ReadonlyVotingRecord) VoteCount(c VoteChoice) int {
	if v := r.count.Get(string(c)); v != nil {
		return v.(int)
	}
	return 0
}

// HasVoted checks if an account already voted.
func (r ReadonlyVotingRecord) HasVoted(user address) bool {
	return r.votes.Has(user.String())
}

// GetVote returns a vote.
func (r ReadonlyVotingRecord) GetVote(user address) (_ Vote, found bool) {
	if v := r.votes.Get(user.String()); v != nil {
		return v.(Vote), true
	}
	return Vote{}, false
}

// VotingRecord stores accounts that voted and vote choices.
type VotingRecord struct {
	ReadonlyVotingRecord
}

// Readonly returns a read only voting record.
func (r VotingRecord) Readonly() ReadonlyVotingRecord {
	return r.ReadonlyVotingRecord
}

// AddVote adds a vote to the voting record.
// If a vote for the same user already exists is overwritten.
func (r *VotingRecord) AddVote(vote Vote) (updated bool) {
	// Get previous member vote if it exists
	v := r.votes.Get(vote.addr.String())

	// When a previous vote exists update counter for the previous choice
	updated = r.votes.Set(vote.addr.String(), vote)
	if updated {
		prev := v.(Vote)
		r.count.Set(string(prev.choice), r.VoteCount(prev.choice)-1)
	}

	r.count.Set(string(vote.choice), r.VoteCount(vote.choice)+1)
	return
}

// TallyDefault applies the constitution's default Council voting rules
// over a proposal's electorate.
//
// Only votes cast by electorate members are counted. The tally denominator
// D is the electorate size minus the number of ABSTAIN votes: abstaining
// shrinks the denominator (deference), while not voting counts against
// passage (silence is opposition). With integer math:
//
//	D = |electorate| - abstains
//	supermajority:   passed    ⇔ D > 0 && 3*yes >= 2*D
//	simple majority: passed    ⇔ D > 0 && 2*yes > D
//	both:            dismissed ⇔ 2*no > D
//
// Passing is checked before dismissal; within one electorate both can never
// hold at once (yes+no <= D makes each pair contradictory). When D is zero
// or negative (an empty electorate, or every member abstained) the outcome
// stays pending: nothing can pass with zero YES votes.
func TallyDefault(r ReadonlyVotingRecord, electorate *addrset.ReadonlySet, t Threshold) Outcome {
	var yes, no, abstain int
	r.Iterate(0, r.Size(), false, func(v Vote) bool {
		if !electorate.Has(v.addr) {
			return false
		}

		switch v.choice {
		case ChoiceYes:
			yes++
		case ChoiceNo:
			no++
		case ChoiceAbstain:
			abstain++
		}
		return false
	})

	d := electorate.Size() - abstain
	if d <= 0 {
		return OutcomePending
	}

	switch t {
	case ThresholdSimpleMajority:
		if 2*yes > d {
			return OutcomePassed
		}
	default:
		if 3*yes >= 2*d {
			return OutcomePassed
		}
	}

	if 2*no > d {
		return OutcomeDismissed
	}
	return OutcomePending
}

// Realm: gno.land/r/<your-namespace>/feles
//
// Feles DAO — three-tier AUTHORITY governance (not weighted, not token-based).
//
//   CORE    the founding team. Final authority. Can do anything, including
//           amending the tiers themselves. Starts at 3, extensible.
//   SENATE  trusted contributors. Propose, vote, and execute within a mandate,
//           but CORE can override or veto any senate decision.
//   MEMBERS the community. Propose and signal; no binding vote.
//
// Authority is ROLE-based: a tier's power comes from its rank, not from a token
// balance or a numeric weight. Within a tier every address is one vote. A Feles
// token, if issued, is a product/treasury asset and is deliberately NOT wired
// into the tally — accumulating tokens can never buy governance power.
//
// Built on gno.land/p/nt/commondao/v0 (verified against chain/pearl source).
// Two CommonDAOs are used so each tier has real, separate voting:
//   coreDAO   — council = CORE members
//   senateDAO — council = SENATE members, parented to coreDAO for override
package feles

import (
	"chain"
	"chain/banker"
	"errors"
	"time"

	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/addrset"
	"gno.land/p/g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m/commondao"
)

// ---- genesis CORE: the founding team --------------------------------------------
// These are the operator's own keys. Whoever holds them holds FINAL AUTHORITY over
// the realm, so they are the one thing to re-check before any redeploy.
//
// With a 2-member council, commondao's supermajority (3*yes >= 2*d) needs BOTH to
// vote yes on a core proposal. Adding a third founder relaxes that to 2 of 3.
var coreSeed = []address{
	"g12e22uqd4jjvvsk6g95re3a44sxuephd5kkrt7m", // Astake — deployer
	"g180zn65f9h588p6qnrh8gnjccgdt2mvpxnzy7us", // Bstake
	// Add the third founder on chain with AddCore once their address exists.
}

var (
	coreDAO   *commondao.CommonDAO // tier 1 — final authority
	senateDAO *commondao.CommonDAO // tier 2 — mandated authority, CORE can override
	memberSet = &addrset.Set{}     // tier 3 — proposal + signal rights only
)

func init() {
	coreOpts := []commondao.Option{
		commondao.WithName("Feles Core"),
		commondao.WithPurpose("Final authority over Feles governance and treasury"),
		commondao.WithProposalKind(treasurySpendKind{}),
	}
	for _, a := range coreSeed {
		coreOpts = append(coreOpts, commondao.WithCouncilMember(a))
	}
	coreDAO = commondao.New(coreOpts...)

	// Senate is parented to Core: that parent link is what makes CORE's authority
	// structural rather than a convention we have to re-check by hand.
	senateDAO = commondao.New(
		commondao.WithName("Feles Senate"),
		commondao.WithPurpose("Delegated authority under Core"),
		commondao.WithParent(coreDAO),
		commondao.WithProposalKind(treasurySpendKind{}),
	)
}

// ---- tier membership -------------------------------------------------------
// Every tier change is a CORE action. Authority flows downward only.

func AddCore(cur realm, who address) {
	assertCore(cur)
	if err := coreDAO.UpdateCouncil([]address{who}, nil); err != nil {
		panic(err)
	}
}

func RemoveCore(cur realm, who address) {
	assertCore(cur)
	if err := coreDAO.UpdateCouncil(nil, []address{who}); err != nil {
		panic(err)
	}
}

func AddSenator(cur realm, who address) {
	assertCore(cur)
	if err := senateDAO.UpdateCouncil([]address{who}, nil); err != nil {
		panic(err)
	}
}

// CORE removes a senator unilaterally — this is the override in practice.
//
// commondao refuses an update that would empty a council (ErrEmptyCouncil), so the
// LAST senator cannot be removed this way. That invariant is a feature for CORE — the
// realm can never become ownerless — but it would otherwise cap CORE's authority over
// the senate. SuspendSenate below is the answer: it disbands the senate's powers
// without violating the library's invariant.
func RemoveSenator(cur realm, who address) {
	assertCore(cur)
	if err := senateDAO.UpdateCouncil(nil, []address{who}); err != nil {
		if err == commondao.ErrEmptyCouncil {
			panic(errors.New("feles: cannot remove the last senator; use SuspendSenate"))
		}
		panic(err)
	}
}

// ---- suspension: CORE disbands the senate's powers wholesale --------------------
// A suspended senate keeps its roster but can do nothing: no new proposals, no votes,
// no execution. This is the disband that ErrEmptyCouncil denies us structurally.

var senateSuspended bool

func SuspendSenate(cur realm) {
	assertCore(cur)
	senateSuspended = true
}

func ResumeSenate(cur realm) {
	assertCore(cur)
	senateSuspended = false
}

func IsSenateSuspended() bool { return senateSuspended }

func assertSenateActive() {
	if senateSuspended {
		panic(errors.New("feles: senate is suspended by core"))
	}
}

// Senate admits members; Core may also admit or remove.
func AddMember(cur realm, who address) {
	caller := cur.Previous().Address()
	if !isCore(caller) && !isSenator(caller) {
		panic(errors.New("feles: core or senate only"))
	}
	memberSet.Add(who)
}

func RemoveMember(cur realm, who address) {
	assertCore(cur)
	memberSet.Remove(who)
}

// ---- proposals -------------------------------------------------------------
// Anyone in any tier may OPEN a treasury proposal. Where it is opened decides
// who votes on it: senate proposals are senate-voted, core proposals core-voted.

func ProposeToSenate(cur realm, to address, denom string, amount int64) uint64 {
	caller := cur.Previous().Address()
	if !isCore(caller) && !isSenator(caller) && !memberSet.Has(caller) {
		panic(errors.New("feles: not a member of any tier"))
	}
	assertSenateActive()
	p, err := senateDAO.Propose(caller, "treasury_spend", spendArgs{to, denom, amount})
	if err != nil {
		panic(err)
	}
	return p.ID()
}

func ProposeToCore(cur realm, to address, denom string, amount int64) uint64 {
	caller := cur.Previous().Address()
	if !isCore(caller) && !isSenator(caller) {
		panic(errors.New("feles: core or senate may escalate to core"))
	}
	p, err := coreDAO.Propose(caller, "treasury_spend", spendArgs{to, denom, amount})
	if err != nil {
		panic(err)
	}
	return p.ID()
}

func VoteSenate(cur realm, proposalID uint64, choice commondao.VoteChoice, reason string) {
	caller := cur.Previous().Address()
	if !isSenator(caller) {
		panic(errors.New("feles: senate only"))
	}
	assertSenateActive()
	if err := senateDAO.Vote(caller, proposalID, choice, reason); err != nil {
		panic(err)
	}
}

func VoteCore(cur realm, proposalID uint64, choice commondao.VoteChoice, reason string) {
	caller := cur.Previous().Address()
	assertCore(cur)
	if err := coreDAO.Vote(caller, proposalID, choice, reason); err != nil {
		panic(err)
	}
}

// ---- execution + override --------------------------------------------------

func ExecuteSenate(cur realm, proposalID uint64) {
	caller := cur.Previous().Address()
	if !isSenator(caller) && !isCore(caller) {
		panic(errors.New("feles: senate or core only"))
	}
	// CORE's override, enforced at the gate: a vetoed proposal never executes,
	// however the senate voted.
	if vetoed[proposalID] {
		panic(errors.New("feles: proposal vetoed by core"))
	}
	assertSenateActive()
	if err := senateDAO.Execute(proposalID, cur); err != nil {
		panic(err)
	}
}

func ExecuteCore(cur realm, proposalID uint64) {
	assertCore(cur)
	if err := coreDAO.Execute(proposalID, cur); err != nil {
		panic(err)
	}
}

// The explicit CORE veto. commondao's `dismiss` is UNEXPORTED and a parent DAO
// has no library-level power over a child's proposals, so the override cannot be
// delegated to the framework — it is enforced here, at the execution gate.
// ExecuteSenate consults this set, so a vetoed proposal can pass its senate vote
// and still never execute. That is what makes CORE final authority in practice.
var vetoed = map[uint64]bool{}

func VetoSenateProposal(cur realm, proposalID uint64) {
	assertCore(cur)
	vetoed[proposalID] = true
}

// CORE can also lift its own veto.
func UnvetoSenateProposal(cur realm, proposalID uint64) {
	assertCore(cur)
	delete(vetoed, proposalID)
}

func IsVetoed(proposalID uint64) bool { return vetoed[proposalID] }

// ---- the custom proposal kind: treasury spend ------------------------------

type spendArgs struct {
	to     address
	denom  string
	amount int64
}

type treasurySpendKind struct{}

func (treasurySpendKind) Name() string { return "treasury_spend" }

func (treasurySpendKind) New(_ commondao.ReadonlyCommonDAO, args any) (commondao.ProposalDefinition, error) {
	a, ok := args.(spendArgs)
	if !ok {
		return nil, errors.New("feles: bad treasury_spend args")
	}
	if a.amount <= 0 || a.denom == "" {
		return nil, errors.New("feles: invalid spend")
	}
	return spendDef{a}, nil
}

type spendDef struct{ a spendArgs }

func (spendDef) Title() string                  { return "Treasury spend" }
func (spendDef) Body() string                   { return "Send coins from the Feles treasury" }
func (spendDef) VotingPeriod() time.Duration    { return 7 * 24 * time.Hour }
func (spendDef) Threshold() commondao.Threshold { return commondao.ThresholdSupermajority }

func (d spendDef) Executor() commondao.ExecFunc {
	return func(_ int, sub realm) error {
		b := banker.NewBanker(banker.BankerTypeRealmSend, sub)
		b.SendCoins(sub.Address(), d.a.to, chain.NewCoins(chain.NewCoin(d.a.denom, d.a.amount)))
		return nil
	}
}

// ---- tier checks -----------------------------------------------------------

func inCouncil(dao *commondao.CommonDAO, a address) bool {
	set := dao.Council()
	found := false
	set.IterateByOffset(0, set.Size(), func(m address) bool {
		if m == a {
			found = true
			return true // stop
		}
		return false
	})
	return found
}

func isCore(a address) bool    { return inCouncil(coreDAO, a) }
func isSenator(a address) bool { return inCouncil(senateDAO, a) }

func assertCore(cur realm) {
	if !isCore(cur.Previous().Address()) {
		panic(errors.New("feles: core only"))
	}
}

// ---- read-only views (for the UI / render) ---------------------------------

func IsCore(a address) bool    { return isCore(a) }
func IsSenator(a address) bool { return isSenator(a) }
func IsMember(a address) bool  { return memberSet.Has(a) }

func Tier(a address) string {
	switch {
	case isCore(a):
		return "CORE"
	case isSenator(a):
		return "SENATE"
	case memberSet.Has(a):
		return "MEMBER"
	default:
		return "NONE"
	}
}

// ---- render ----------------------------------------------------------------
// What gno.land shows for this realm. The tier roster is the governance state
// worth publishing: who holds authority is exactly what a member needs to check.

func Render(path string) string {
	out := "# Feles DAO\n\n"
	out += "Three-tier authority governance. Within a tier, one address is one vote;\n"
	out += "authority comes from rank, not from any token balance.\n\n"

	out += "## Core — final authority\n\n"
	council := coreDAO.Council()
	council.IterateByOffset(0, council.Size(), func(a address) bool {
		out += "- " + a.String() + "\n"
		return false
	})

	out += "\n## Senate — delegated authority\n\n"
	if senateSuspended {
		out += "**SUSPENDED by Core.** The roster below holds no powers.\n\n"
	}
	sc := senateDAO.Council()
	if sc.Size() == 0 {
		out += "_No senators appointed._\n"
	}
	sc.IterateByOffset(0, sc.Size(), func(a address) bool {
		out += "- " + a.String() + "\n"
		return false
	})

	out += "\n## Members — propose and signal\n\n"
	if memberSet.Size() == 0 {
		out += "_No members yet._\n"
	}
	memberSet.IterateByOffset(0, memberSet.Size(), func(a address) bool {
		out += "- " + a.String() + "\n"
		return false
	})
	return out
}

package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1fqcddarc4s9qap788t7lksgag4mq7g2gevc8ht"), 5),
		},
		"Add 1 validator(s) to the valset",
		"Batch-add 1 operator(s) to the active valset with voting power 5.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package nsview

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

/*
A HAND-DRAWN ALPHABET, STORED ONCE.

WHY THIS EXISTS. Every renderer that shows these cards — wallets,
marketplaces, block explorers — puts the SVG in a sandbox with no
network. A web font therefore never loads; it silently substitutes, and
the display lettering the mockups were designed around turns into
whatever that particular viewer happens to default to. Only the generic
families (serif, sans-serif, monospace) can be relied on, and none of
them is a marker pen.

The only way to get identical letterforms on every device is to ship the
letters themselves. These are strokes, not outlines: a path with a round
cap and a thick stroke looks like a pen, costs a fraction of the data an
outline font would, and scales without a second set of hinting.

THESE LETTERFORMS ARE OUR OWN. They are not traced from, derived from, or
measured against any existing typeface. A typeface is somebody's design
and often somebody's licensed asset; drawing our own marker capitals is
both cheaper and the only version we are entitled to put on chain
permanently. The house rule elsewhere on this project is "original art in
the spirit of the thing", and a font is art.

WHAT IT COSTS. Storage is 100 ugnot a byte and permanent, so the
encoding is deliberately dense rather than readable: each point is two
characters, each stroke is a run of points, strokes are separated by "|".
The whole alphabet — twenty-six letters, ten digits, and the punctuation
this project actually uses — is well under a kilobyte. An outline font
would have been tens of kilobytes and unreadable besides.

THE GRID. Ten wide by fourteen tall, origin top-left, so a glyph reads
directly as coordinates: "0d" is the bottom-left corner and "47" is the
middle. x never exceeds 9, so it is always one digit; y reaches 13, so
10..13 are written a..d.
*/

// glyph returns the stroke encoding for one character, or "" for
// anything unknown — an unknown character draws nothing rather than a
// box, because this markup lands inside a token that other people's
// software renders and a missing letter is better than a wrong one.
func glyph(c byte) string {
	switch c {
	// Generated from a readable point table rather than typed by
	// hand: forty glyphs of paired coordinate characters is precisely
	// the job where one stray character shifts a whole letter by one and
	// nobody spots it until it is on chain forever.
	case 'A':
		return "0d409d|2878"
	case 'B':
		return "000d|006206|06790d"
	case 'C':
		return "824014194d8b"
	case 'D':
		return "000d|00737a0d"
	case 'E':
		return "80000d8d|0666"
	case 'F':
		return "80000d|0666"
	case 'G':
		return "824014194d8b8757"
	case 'H':
		return "000d|909d|0696"
	case 'I':
		return "2070|404d|2d7d"
	case 'J':
		return "707a4d1a"
	case 'K':
		return "000d|8007|359d"
	case 'L':
		return "000d8d"
	case 'M':
		return "0d1047809d"
	case 'N':
		return "0d009d90"
	case 'O':
		return "4014194d898440"
	case 'P':
		return "0d00727507"
	case 'Q':
		return "4014194d898440|6a9d"
	case 'R':
		return "0d00727507|379d"
	case 'S':
		return "824013678a4d1b"
	case 'T':
		return "0090|404d"
	case 'U':
		return "00094d8980"
	case 'V':
		return "004d90"
	case 'W':
		return "002d457d90"
	case 'X':
		return "009d|900d"
	case 'Y':
		return "004790|474d"
	case 'Z':
		return "00900d9d"
	case '0':
		return "4014194d898440|2974"
	case '1':
		return "23404d|2d7d"
	case '2':
		return "1340830d9d"
	case '3':
		return "11508446|46895d1b"
	case '4':
		return "7d700999"
	case '5':
		return "80101666895d1b"
	case '6':
		return "7140151a5d8a5718"
	case '7':
		return "00903d"
	case '8':
		return "4613407346194d7946"
	case '9':
		return "8647144084895d2c"
	case '*':
		return "424a|1479|7419"
	case '-':
		return "1787"
	case '.':
		return "4c4d"
	case '!':
		return "4049|4c4d"
	case '?':
		return "1340734749|4c4d"
	case '\'':
		return "4043"
	case ' ':
		return ""
	}
	return ""
}

const (
	glyphW  = 10 // grid width of one glyph
	glyphH  = 14 // grid height, top to bottom
	glyphAd = 12 // advance: glyph width plus the gap to the next one
)

// hexish decodes one coordinate character. Digits are themselves; a..d
// carry 10..13, which is the only reason y can exceed nine in two
// characters.
func hexish(c byte) int {
	if c >= '0' && c <= '9' {
		return int(c - '0')
	}
	if c >= 'a' && c <= 'd' {
		return int(c-'a') + 10
	}
	return -1
}

/*
MarkerText draws a line of text as stroked paths.

`size` is the CAP HEIGHT in user units, not an em size: it is the height
of a capital letter, which is the measurement anybody positioning this by
eye is actually thinking in.

`x` is the left edge and `y` is the TOP of the capitals, matching how the
rest of this file positions things and unlike SVG's own text baseline,
which is a trap when mixing the two.

The jitter is what makes it read as a pen rather than a plotter. It is
derived from the character and its position, so it is stable: the same
string renders identically on every read, which matters because these
cards are regenerated constantly and a letter that wobbled between reads
would look like a rendering fault.
*/
func MarkerText(s string, x, y, size int, colour string, weight int) string {
	if s == "" || size <= 0 {
		return ""
	}
	if weight <= 0 {
		weight = 1 + size/7
	}
	var out strings.Builder
	out.WriteString(ufmt.Sprintf(
		`<g fill="none" stroke="%s" stroke-width="%d" stroke-linecap="round" stroke-linejoin="round">`,
		colour, weight))

	up := strings.ToUpper(s)
	for i := 0; i < len(up); i++ {
		enc := glyph(up[i])
		if enc == "" {
			continue
		}
		ox := x + i*glyphAd*size/glyphH
		out.WriteString(strokes(enc, ox, y, size, i))
	}
	out.WriteString(`</g>`)
	return out.String()
}

// strokes turns one glyph's encoding into path elements at a position.
func strokes(enc string, ox, oy, size, idx int) string {
	var out strings.Builder
	for _, run := range strings.Split(enc, "|") {
		d := ""
		n := 0
		for j := 0; j+1 < len(run); j += 2 {
			gx := hexish(run[j])
			gy := hexish(run[j+1])
			if gx < 0 || gy < 0 {
				continue // a space inside an encoding is padding, not a point
			}
			// Scale from the grid to cap height, then nudge. The nudge is
			// at most one unit and comes from a fixed mix of the glyph
			// index and the point index, so it never changes between reads.
			px := ox + gx*size/glyphH
			py := oy + gy*size/glyphH
			px += wobble(idx*7 + j*3)
			py += wobble(idx*5 + j*11 + 1)
			if n == 0 {
				d += ufmt.Sprintf("M%d %d", px, py)
			} else {
				d += ufmt.Sprintf("L%d %d", px, py)
			}
			n++
		}
		if n > 1 {
			out.WriteString(`<path d="` + d + `"/>`)
		} else if n == 1 {
			// A single point would draw nothing without a round cap on a
			// zero-length path, which not every renderer honours. Give it
			// a hair of length instead.
			out.WriteString(`<path d="` + d + `l1 0"/>`)
		}
	}
	return out.String()
}

// wobble is a tiny deterministic offset in the range -1..1. Not random:
// the cards are regenerated on every read, and anything genuinely random
// would make the lettering shimmer.
func wobble(seed int) int {
	return (seed*2654435761)%3 - 1
}

// MarkerWidth is what MarkerText will occupy, so a caller can centre it.
// Counts every character including the ones that draw nothing, because a
// space still advances.
func MarkerWidth(s string, size int) int {
	if s == "" {
		return 0
	}
	return len(s) * glyphAd * size / glyphH
}

// MarkerCentred draws text centred on cx, which is what almost every
// caller here wants and what the SVG text-anchor attribute would have
// done for them if a font had been available.
func MarkerCentred(s string, cx, y, size int, colour string, weight int) string {
	return MarkerText(s, cx-MarkerWidth(s, size)/2, y, size, colour, weight)
}

package nsview

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

// Seasonal decoration, driven by DATA rather than by code.
//
// The card is generated on every read, so anything it draws can change
// after names have been sold. That makes a holiday overlay possible —
// snow in December, falling leaves in October — across every token at
// once. The temptation is to write a drawSnow() into this realm and a
// drawPumpkins() next year, which would make every new decoration a
// redeploy of the view.
//
// So it is parameterised instead. This realm knows how to draw drifting
// particles; WHICH particles, what colour, how many and until when live
// in a global that any admin call can rewrite. Christmas is then one
// transaction, not a deployment, and so is turning it off.
//
// Format, read from the global key `cardfx`:
//
//	dir:fall;n:22;c:#ffffff;c2:#dbeafe;s:3;d:9;until:1767225600
//
//	dir    fall | rise | burst    drift down, drift up, or fireworks
//	n      1..40                  how many
//	c      #rrggbb                colour (c2, c3 optional, cycled)
//	s      1..6                   pixel size
//	d      2..30                  seconds for one traverse (lower = faster)
//	sv     0..3                   size jitter, so they are not all identical
//	k      4..16                  sparks per shell, when dir is burst
//	sh     sq | leaf | petal      particle shape; leaf and petal are angled
//	until  unix seconds, 0 = no expiry
//
// `until` matters more than it looks: an overlay that expires on its own
// cannot be forgotten in January. Everything is parsed defensively and a
// malformed value yields NO overlay, for the same reason the sprite
// parser does — this markup lands inside a token that other people's
// software renders.
const keyFX = "cardfx"

func overlaySVG(now int64) string {
	return buildOverlay(nsdata.GetGlobal(keyFX), now)
}

// A SCHEDULE, so December snows without anybody remembering to make it.
//
// This is free in a way the treasury swap was not. That needed somebody
// to send a transaction, because a realm cannot act on its own. This
// needs nobody, because the card is generated on every read and can
// simply look at the clock — the decoration is a rendering decision, not
// an action.
//
// Rules are separated by "|" and the FIRST one whose window contains
// today wins, so put the specific ones first:
//
//	from:12-01;to:01-06;dir:fall;n:26;c:#ffffff|from:10-24;to:11-02;dir:rise;n:22;c:#f97316
//
// from/to are MM-DD and RECUR every year, which is the point — set it
// once and every December snows. A window whose start is after its end
// wraps the new year, so 12-01 to 01-06 is what you would expect rather
// than an empty range. A rule with no window is always eligible, so a
// bare spec still behaves as it did.
func pickRule(spec string, now int64) string {
	if spec == "" {
		return ""
	}
	t := time.Unix(now, 0).UTC()
	today := int(t.Month())*100 + t.Day()
	for _, rule := range strings.Split(spec, "|") {
		/* A WEEKDAY RULE, for the one date that is not a date.
		 *
		 * Friday the thirteenth falls one to three times a year and never
		 * on a schedule, so it cannot be written as a MM-DD window. `on`
		 * takes a weekday and an optional day-of-month — on:fri-13 — and
		 * is checked before the window fields so a rule can use either
		 * without the two interfering.
		 *
		 * Deliberately narrow: this is not a general calendar language,
		 * it is the one shape the existing one could not express. */
		if on := ruleField(rule, "on"); on != "" {
			if weekdayMatch(on, t) {
				return rule
			}
			continue
		}
		from := ruleField(rule, "from")
		to := ruleField(rule, "to")
		if from == "" && to == "" {
			return rule // no window: always eligible
		}
		f, okF := mmdd(from)
		e, okE := mmdd(to)
		if !okF || !okE {
			continue // a malformed window disables its rule, not the lot
		}
		if f <= e {
			if today >= f && today <= e {
				return rule
			}
		} else if today >= f || today <= e {
			// wraps the year end, e.g. 12-01 to 01-06
			return rule
		}
	}
	return ""
}

func ruleField(rule, key string) string {
	for _, part := range strings.Split(rule, ";") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) == 2 && strings.TrimSpace(kv[0]) == key {
			return strings.TrimSpace(kv[1])
		}
	}
	return ""
}

// mmdd reads "12-01" into 1201. Rejects anything that is not a real
// calendar date, so a typo cannot silently make a rule match all year.
func mmdd(s string) (int, bool) {
	if len(s) != 5 || s[2] != '-' {
		return 0, false
	}
	m, err1 := strconv.Atoi(s[:2])
	d, err2 := strconv.Atoi(s[3:])
	if err1 != nil || err2 != nil || m < 1 || m > 12 || d < 1 || d > 31 {
		return 0, false
	}
	return m*100 + d, true
}

func buildOverlay(spec string, now int64) string {
	spec = pickRule(spec, now)
	if spec == "" {
		return ""
	}
	dir := "fall"
	n := 0
	size := 3
	dur := 9
	jitter := 0
	sparks := 8
	shape := "sq"
	var until int64
	cols := []string{}

	for _, part := range strings.Split(spec, ";") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) != 2 {
			continue
		}
		k, v := strings.TrimSpace(kv[0]), strings.TrimSpace(kv[1])
		switch k {
		case "dir":
			if v == "fall" || v == "rise" || v == "burst" {
				dir = v
			}
		case "n":
			n = atoiClamp(v, 0, 40)
		case "s":
			size = atoiClamp(v, 1, 6)
		case "d":
			// Floor of 2, not 3: a 3-second traverse was the fastest the
			// card could go, and rain wants to be faster than snow by more
			// than that allows.
			dur = atoiClamp(v, 2, 30)
		case "sv":
			jitter = atoiClamp(v, 0, 3)
		case "k":
			sparks = atoiClamp(v, 4, 16)
		case "sh":
			if v == "sq" || v == "leaf" || v == "petal" {
				shape = v
			}
		case "until":
			if x, err := strconv.ParseInt(v, 10, 64); err == nil && x >= 0 {
				until = x
			}
		case "c", "c2", "c3":
			if isHexColour(v) {
				cols = append(cols, v)
			}
		}
	}

	if n <= 0 || len(cols) == 0 {
		return ""
	}
	// Expired decoration draws nothing, so a forgotten overlay retires
	// itself rather than snowing in July.
	if until > 0 && now >= until {
		return ""
	}

	if dir == "burst" {
		return fireworks(n, sparks, size, dur, cols)
	}

	var b strings.Builder
	b.WriteString(`<g opacity="0.85">`)
	for i := 0; i < n; i++ {
		// Deterministic scatter: the same token renders identically on
		// every read, which matters because a marketplace may cache it.
		h := hash(i)
		x := int(h % 392)
		delay := int(h/7) % (dur * 10)
		drift := int(h/13)%14 - 7
		wobble := dur + int(h/17)%5
		from, to := -12, 412
		if dir == "rise" {
			from, to = 412, -12
		}
		col := cols[i%len(cols)]
		// Not all the same size. Uniform particles read as a texture;
		// a little variation reads as depth, for two bytes of spec.
		px := size
		if jitter > 0 {
			px = size + int(h/23)%(jitter+1)
		}
		if shape == "sq" {
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s">`+
					`<animateTransform attributeName="transform" type="translate" `+
					`values="0 0;%d %d" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
				x, from, px, px, col,
				drift, to-from, wobble, delay/10, delay%10))
			continue
		}
		// A shaped particle needs its own rotation, and an element can
		// carry only one transform. Animating the group and rotating the
		// shape inside it keeps the two independent — animating both on
		// one element would make each leaf drift along its own angle
		// instead of downward.
		b.WriteString(ufmt.Sprintf(
			`<g><animateTransform attributeName="transform" type="translate" `+
				`values="0 0;%d %d" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>%s</g>`,
			drift, to-from, wobble, delay/10, delay%10,
			shapeAt(shape, x, from, px, int(h/31)%360, col)))
	}
	b.WriteString(`</g>`)
	return b.String()
}

// A small deterministic spread. Not random: the same index must always
// give the same particle, or a cached render and a fresh one disagree.
func hash(i int) int {
	h := (i+1)*2654435761 ^ 0x9e3779b9
	if h < 0 {
		h = -h
	}
	return h
}

func atoiClamp(s string, lo, hi int) int {
	v, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Fireworks: a shell climbs, vanishes, and throws sparks outward.
//
// The cost question is worth answering plainly, because it is the first
// decoration that is not one rect per particle. A shell is 1 rect for
// the climb plus k rects for the burst, so `n:5;k:10` is 55 rects — the
// same order as the 34 the rain already draws, and a fifth of the 128
// the domain sprite draws on every card anyway. None of it is stored:
// the card is built during a read, so this costs no gas and no storage,
// only the browser's time. That is the real ceiling, so the totals are
// capped below rather than left to whoever writes the spec.
//
// Two phases in one loop, driven by keyTimes on a single animation each,
// because a <set> chain or nested <g> would double the element count for
// the same picture.
func fireworks(shells, sparks, size, dur int, cols []string) string {
	if shells > 6 {
		shells = 6 // 6 x 16 sparks is already 102 rects
	}
	var b strings.Builder
	b.WriteString(`<g opacity="0.9">`)
	for i := 0; i < shells; i++ {
		h := hash(i * 7)
		x := 40 + int(h%340)          // keep the burst off the very edge
		burstY := 96 + int(h/11)%140  // where it stops climbing
		lift := 400 - burstY          // how far it climbs from the base
		// Shells are staggered across the cycle so they do not all go up
		// together, and each has its own colour from the palette.
		begin := int(h/29) % (dur * 10)
		// One colour per shell, not one per spark. A real firework is a
		// single charge, and mixing colours inside one burst reads as
		// confetti rather than pyrotechnics.
		col := cols[i%len(cols)]

		// The climb. Held at the top for the rest of the cycle rather
		// than looping straight away, and faded out at the moment of the
		// burst so the eye reads one event, not two objects.
		b.WriteString(ufmt.Sprintf(
			`<rect x="%d" y="400" width="%d" height="%d" fill="%s" opacity="0">`+
				`<animateTransform attributeName="transform" type="translate" `+
				`values="0 0;0 -%d;0 -%d" keyTimes="0;0.4;1" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>`+
				`<animate attributeName="opacity" values="1;1;0;0" keyTimes="0;0.38;0.4;1" `+
				`dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
			x, size, size, col, lift, lift, dur, begin/10, begin%10, dur, begin/10, begin%10))

		for j := 0; j < sparks; j++ {
			g := hash(i*97 + j*13)
			d := j * 16 / sparks // one of the 16 fixed directions
			r := 34 + int(g%34)  // how far this spark travels
			dx := r * dirCos[d] / 100
			dy := r * dirSin[d] / 100
			// Sparks fall as they fly, which is the whole difference
			// between a firework and a starburst.
			dy += r / 3
			px := size
			if int(g/7)%3 == 0 {
				px = size + 1 // a few brighter, bigger sparks per shell
			}
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s" opacity="0">`+
					`<animateTransform attributeName="transform" type="translate" `+
					`values="0 0;0 0;%d %d" keyTimes="0;0.4;1" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>`+
					`<animate attributeName="opacity" values="0;0;1;0" keyTimes="0;0.4;0.52;1" `+
					`dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
				x, burstY, px, px, col,
				dx, dy, dur, begin/10, begin%10, dur, begin/10, begin%10))
		}
	}
	b.WriteString(`</g>`)
	return b.String()
}

// Sixteen directions on a circle, as hundredths. A table rather than
// math.Sin: the same integers must come out on every node, and this is
// the whole of the trigonometry the card needs.
var (
	dirCos = [16]int{100, 92, 71, 38, 0, -38, -71, -92, -100, -92, -71, -38, 0, 38, 71, 92}
	dirSin = [16]int{0, 38, 71, 92, 100, 92, 71, 38, 0, -38, -71, -92, -100, -92, -71, -38}
)

// shapeAt draws one non-square particle at a position, turned to its own
// angle. Leaves and petals are two curves each rather than a polygon: a
// leaf is pointed at both ends, a petal is round at one, and that single
// difference is the whole of what distinguishes October from April.
//
// The numbers are derived from the particle size so `s` still means what
// it means everywhere else, and both shapes stay legible at the size a
// card is actually looked at.
func shapeAt(kind string, x, y, px, ang int, col string) string {
	w, hh := px, px*2
	switch kind {
	case "leaf":
		// Wider than a petal at the same size. A lens with its control
		// points at the particle width is a sliver, not a leaf.
		w = px * 3 / 2
		return ufmt.Sprintf(
			`<path d="M0 -%dQ%d 0 0 %dQ-%d 0 0 -%dZ" fill="%s" transform="translate(%d,%d) rotate(%d)"/>`,
			hh, w, hh, w, hh, col, x, y, ang)
	case "petal":
		return ufmt.Sprintf(
			`<ellipse rx="%d" ry="%d" fill="%s" transform="translate(%d,%d) rotate(%d)"/>`,
			w, hh, col, x, y, ang)
	}
	return ufmt.Sprintf(`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`, x, y, px, px, col)
}

// weekdayMatch reads "fri" or "fri-13": a weekday, optionally pinned to a
// day of the month. Anything it does not understand matches nothing, so a
// typo disables its own rule rather than firing every day.
func weekdayMatch(spec string, t time.Time) bool {
	day := ""
	dom := 0
	if at := strings.Index(spec, "-"); at > 0 {
		day = spec[:at]
		n, err := strconv.Atoi(spec[at+1:])
		if err != nil || n < 1 || n > 31 {
			return false
		}
		dom = n
	} else {
		day = spec
	}
	names := map[string]time.Weekday{
		"sun": time.Sunday, "mon": time.Monday, "tue": time.Tuesday,
		"wed": time.Wednesday, "thu": time.Thursday, "fri": time.Friday,
		"sat": time.Saturday,
	}
	want, ok := names[strings.ToLower(day)]
	if !ok {
		return false
	}
	if t.Weekday() != want {
		return false
	}
	return dom == 0 || t.Day() == dom
}

// Package nsview is the human-facing view — the third realm in the
// split, and the newest (2026-08-21).
//
// It exists because an adversarial review found three defects in the old
// Render(), which lived inside the permanent `nsdata` vault: unescaped
// profile text injected into the page markdown, an O(domains × names)
// home page any user could inflate into a permanent denial of service,
// and navigation links that 404'd. All three were display bugs, and none
// of them could ever have been fixed, because that realm is deployed
// exactly once. The NFT artwork moved here for the same reason.
//
// Display code is swappable now. This realm holds no state, reads
// everything from nsdata's exported API, and can be redeployed and
// re-pointed at any time with nothing to migrate.
package nsview

import (
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

// Profile keys inside a name's extension slot. Conventions owned by this
// realm and the logic realm, not by the vault — the vault stores strings
// and has no opinion about what they mean.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
)

func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "token/"):
		return "```\n" + BuildSVG(strings.TrimPrefix(path, "token/")) + "\n```\n"
	default:
		label, domainLabel := splitTokenID(path)
		if label == "" {
			return renderDomain(domainLabel)
		}
		return renderName(label, domainLabel)
	}
}

func renderHome() string {
	out := "# Meme Name Service\n\n"
	out += ufmt.Sprintf("%d domains registered.\n\n", nsdata.CountDomains())
	for _, label := range splitCSV(nsdata.ListDomains()) {
		owner, _, _, _, _ := nsdata.GetDomainInfo(label)
		// The link target must carry the "*" prefix — Render dispatches a
		// bare label to renderName, which 404s. That was the old home
		// page's bug: every link on it was dead.
		out += ufmt.Sprintf("- [*%s](*%s) — owner `%s` — %d name(s)\n",
			label, label, owner.String(), nsdata.CountNames(label))
	}
	return out
}

func renderDomain(domainLabel string) string {
	if !nsdata.DomainExists(domainLabel) {
		return "404: unknown domain\n"
	}
	owner, registered, expires, streak, frozen := nsdata.GetDomainInfo(domainLabel)
	status, _ := statusFields(expires, frozen)
	daysLine := remaining(expires, time.Now().Unix())

	out := ufmt.Sprintf("# *%s\n\n", domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", time.Unix(registered, 0).UTC().Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)

	count := nsdata.CountNames(domainLabel)
	out += ufmt.Sprintf("## %d name(s) under this domain\n\n", count)
	for _, label := range splitCSV(nsdata.ListNames(domainLabel)) {
		out += ufmt.Sprintf("- [%s*%s](%s*%s)\n", label, domainLabel, label, domainLabel)
	}
	if count == 0 {
		out += "_none yet_\n"
	}
	return out
}

func renderName(label, domainLabel string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return "404: unknown name\n"
	}
	owner, registered, expires, streak, frozen, isNFT := nsdata.GetNameInfo(label, domainLabel)
	status, _ := statusFields(expires, frozen)
	daysLine := remaining(expires, time.Now().Unix())

	out := ufmt.Sprintf("# %s*%s\n\n", label, domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	if !isNFT {
		out += "- free tier (no token minted yet)\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", time.Unix(registered, 0).UTC().Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)
	out += ufmt.Sprintf("- [*%s](*%s)\n\n", domainLabel, domainLabel)

	displayName := nsdata.GetNameExtra(label, domainLabel, keyDisplayName)
	bio := nsdata.GetNameExtra(label, domainLabel, keyBio)
	website := nsdata.GetNameExtra(label, domainLabel, keyWebsite)

	if displayName != "" || bio != "" || website != "" {
		out += "## Profile\n\n"
		// Every one of these is attacker-authored. Escaping them is the
		// whole reason this realm exists separately.
		if displayName != "" {
			out += ufmt.Sprintf("**%s**\n\n", escapeMarkdown(displayName))
		}
		if bio != "" {
			// A blockquote so even a crafted multi-line bio cannot break
			// out into block-level constructs.
			out += "> " + escapeMarkdown(bio) + "\n\n"
		}
		if website != "" {
			if isSafeURL(website) {
				out += ufmt.Sprintf("[%s](%s)\n\n", escapeMarkdown(website), website)
			} else {
				out += ufmt.Sprintf("website (unverified): `%s`\n\n", escapeMarkdown(website))
			}
		}
	}
	return out
}

// -- helpers --

func splitCSV(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

// splitTokenID splits `label*domain`; a leading "*" yields an empty
// label, which is how a domain page is addressed.
func splitTokenID(tid string) (label, domain string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

// escapeMarkdown neutralises user-authored text so it renders as the
// literal characters typed rather than as markup. Backslash-escapes the
// CommonMark ASCII punctuation set and folds newlines, which stops
// headings, lists, tables, images, links, and raw HTML alike.
func escapeMarkdown(s string) string {
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if strings.IndexByte("\\`*_{}[]()#+-.!|<>&~\"'", c) >= 0 {
			b.WriteByte('\\')
		}
		b.WriteByte(c)
	}
	return b.String()
}

// isSafeURL only admits plain http/https. Everything else — javascript:,
// data:, anything unrecognised — is refused a live link. Checked on read
// rather than on write so tightening the rule later also applies to
// profiles that already exist.
func isSafeURL(u string) bool {
	if !strings.HasPrefix(u, "http://") && !strings.HasPrefix(u, "https://") {
		return false
	}
	if len(u) > 256 {
		return false
	}
	// This value is emitted RAW as the markdown link destination, so it is
	// the one attacker-authored string on the page that escapeMarkdown
	// does not neutralise. Allow-list instead of deny-list: every byte
	// must be printable, non-space ASCII. A deny-list missed newlines,
	// which let a crafted `website` terminate the link and inject
	// arbitrary markdown into the page below it.
	for i := 0; i < len(u); i++ {
		c := u[i]
		if c <= 0x20 || c >= 0x7f {
			return false
		}
		if strings.IndexByte("()<>\"'\\`", c) >= 0 {
			return false
		}
	}
	return true
}

package nsview

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

/*
THE SKIN'S OWN CARD — what a skin token looks like when it is the thing
being listed, rather than the thing decorating a name.

WHY IT EXISTS. A skin is a separate token (see SKINS.md §1), so it has
its own listing on any marketplace that shows it. Drawn the way a name
card is drawn — art edge to edge, big lettering over the top — the two
would be indistinguishable, and somebody would buy a picture believing
they had bought a name. That is not a subtle risk: it is the single most
likely way this product hurts somebody.

THE FRAME IS THE WHOLE IDEA. A name card is FULL BLEED; this one is
MATTED, with the art inset inside a border and bands of ground above and
below it. The distinction survives at thumbnail size, at a glance, with
no text read at all — which is the only size and attention a marketplace
grid actually gets. The word SKIN across the top is the confirmation, not
the mechanism.

IT NAMES ITSELF, and it says what it will not go on. An extension-locked
skin that does not say so is a support ticket per sale.

WHAT IT DELIBERATELY DOES NOT SHOW: a price, an edition number, a rarity,
or anything else that frames the object as an investment. That rule is
from the risk policy and it applies to the artwork as much as to the copy
on the site — the card travels to places our words do not.
*/

// The matte. A name card uses all 400; this one is inset, and the inset
// is the tell.
const (
	skinTop  = 74 // the band the word SKIN sits in
	skinFoot = 62 // the band the skin's own name sits in

	// THE ART IS SQUARE, and its size is whatever the SHORTER dimension
	// allows — which is the height, because the two label bands eat into
	// it and the sides only give up a margin.
	//
	// This started as "340 wide" and was wrong: 340 is what the width
	// allows, but only 264 of height remains once the bands are taken,
	// so the art ran 76px down into the footer and sat behind the skin's
	// own name. A square sprite drawn into a non-square box either
	// stretches or overflows, and both are worse than being smaller.
	skinBox = 400 - skinTop - skinFoot // 264
	// Centred on what is left, so the side margins come out equal.
	skinPad = (400 - skinBox) / 2 // 68
)

/*
skinArtSVG renders a sprite to fill a box, INFERRING THE GRID from the
data rather than assuming twelve.

spriteSVG hardcodes twelve in four places, which is right for the domain
artwork it was written for and wrong here: SKINS.md §2a offers 12, 16, 24
and 32, and the whole point of inferring is that one format then covers
every size and every sprite already on chain keeps working.

Validation is spriteSVG's, unchanged and unrelaxed, because it is not
merely a parser — it is the thing standing between community-authored
data and markup inside somebody else's wallet. Any violation rejects the
WHOLE sprite rather than skipping the bad part: a partial picture hides
the fault.
*/
func skinArtSVG(enc string, ox, oy, box int) string {
	if enc == "" {
		return ""
	}
	parts := strings.Split(enc, "|")
	n := len(parts) - 1
	if n < 4 || n > 64 {
		return ""
	}
	colours := map[string]string{}
	for _, entry := range strings.Split(parts[0], ",") {
		if len(entry) != 8 || entry[1] != '#' {
			return ""
		}
		if !isHexColour(entry[1:]) {
			return ""
		}
		colours[entry[:1]] = entry[1:]
	}

	/*
		EVERY CELL IS PLACED FROM ITS OWN EXACT BOUNDARY, never from an
		accumulated cell size.

		The obvious way — cell := box / n, then x*cell — truncates once
		and then repeats the error n times, so the art stops short of its
		own frame by up to n pixels. Scaling the cell by a thousand first
		does not fix it either: at n=12 in a 340 box the cell is 28.333,
		28333 x 12 is 339996, and the last column still lands a pixel
		inside the frame. Which is a full pixel of bare matte down one
		edge, and by eye it reads as a design choice rather than a bug.

		Computing each boundary as x*box/n instead makes the LAST one
		exactly n*box/n = box, at every grid size, with no accumulation
		to go wrong.

		RUNS OF ONE COLOUR BECOME ONE RECT, which SKINS.md §2a asked for
		before the grid went much past 32 and which the collection has now
		made urgent rather than tidy.

		Every painted cell used to emit its own <rect>, inside every
		wallet that renders the card. That is tolerable for a sprite of a
		thing and ruinous for a BACKGROUND: a vertical gradient is one
		colour per row, so a 32-wide one emitted 1,024 rects to draw 32
		distinct bands. Merging horizontal runs draws it in 32 — the same
		picture, pixel for pixel, at a thirty-second of the markup.

		It costs nothing when it does not apply. A busy sprite with no
		horizontal runs merges nothing and emits exactly what it did
		before.
	*/
	var b strings.Builder
	for y := 1; y <= n; y++ {
		row := parts[y]
		if len(row) != n {
			return ""
		}
		y0 := oy + (y-1)*box/n
		h := oy + y*box/n - y0
		for x := 0; x < n; {
			ch := row[x : x+1]
			if ch == "." {
				x++
				continue
			}
			c, ok := colours[ch]
			if !ok {
				return ""
			}
			// How far this colour runs.
			run := x + 1
			for run < n && row[run:run+1] == ch {
				run++
			}
			x0 := ox + x*box/n
			w := ox + run*box/n - x0
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`,
				x0, y0, w, h, c))
			x = run
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return b.String()
}

/*
SkinCardSVG draws a skin token's own listing card.

	name   the skin's name, as the shop shows it
	art    the sprite string
	lock   the extension it is restricted to, or "" for one that goes
	       on any name
	light  true  = pale lettering on a dark matte
	       false = dark lettering on a pale matte

The return is a whole document rather than a fragment, because unlike the
nameplate this composites over nothing — it IS the card.
*/
func SkinCardSVG(name, art, lock string, light bool) string {
	ink, edge, matte := "#f4f4f5", "#26262b", "#0b0d10"
	if !light {
		ink, edge, matte = "#0b0d10", "#d4d4d8", "#f4f4f5"
	}

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`)
	b.WriteString(ufmt.Sprintf(`<rect width="400" height="400" fill="%s"/>`, matte))

	// THE WORD, big and flat across the top. Monospace and letter-spaced
	// so it reads as a label on the object rather than as a title for it.
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="46" font-family="monospace" font-size="27" font-weight="bold"`+
			` letter-spacing="7" fill="%s">SKIN</text>`, skinPad, ink))

	// The art, inset, with a frame drawn AROUND it rather than over it —
	// a border that overlapped would eat a row of somebody's pixels.
	inner := skinArtSVG(art, skinPad, skinTop, skinBox)
	if inner == "" {
		// A skin whose art will not parse still has to render as
		// something, or the listing is a blank square with no clue why.
		b.WriteString(ufmt.Sprintf(
			`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s"`+
				` stroke-width="2" stroke-dasharray="7 6"/>`,
			skinPad, skinTop, skinBox, skinBox, edge))
		b.WriteString(ufmt.Sprintf(
			`<text x="200" y="%d" text-anchor="middle" font-family="monospace"`+
				` font-size="13" fill="%s">ART WILL NOT RENDER</text>`,
			skinTop+skinBox/2, edge))
	} else {
		b.WriteString(inner)
	}
	b.WriteString(ufmt.Sprintf(
		`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s" stroke-width="2"/>`,
		skinPad-1, skinTop-1, skinBox+2, skinBox+2, edge))

	// The skin's own name, and what it will not go on.
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="%d" font-family="sans-serif" font-size="21" font-weight="bold"`+
			` fill="%s">%s</text>`,
		skinPad, 400-skinFoot+34, ink, esc(name)))

	tail := "goes on any name"
	if lock != "" {
		tail = "*" + lock + " names only"
	}
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="%d" text-anchor="end" font-family="monospace" font-size="12"`+
			` letter-spacing="1" fill="%s">%s</text>`,
		400-skinPad, 400-skinFoot+34, edge, esc(strings.ToUpper(tail))))

	b.WriteString(`</svg>`)
	return b.String()
}

package nsview

import (
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

/*
SKINS — the card becomes something else entirely for a day.

The decoration calendar already draws snow and embers ON TOP of a card.
A skin REPLACES it: on 22 May the token is a pizza, on 3 January it is a
newspaper. That is a different kind of change, so it is a different
field, and any date without one renders exactly as it always has.

HOW A CONTRACT KNOWS THE DATE AT ALL. It does not read a block height and
guess. Every block carries a timestamp in its header, agreed by consensus
the same way its transactions are, and `time.Now()` inside a realm returns
that block time. So a realm has a real clock, accurate to within a block
interval — which for a decoration that changes once a year is precision
nobody will ever notice. This is the same mechanism the seasonal overlay
has always used.

WHY THIS COSTS NOTHING TO RUN. The card is generated on every read rather
than fixed at mint, so a skin needs no transaction, no migration and
nobody awake at midnight. It applies to names sold years ago. Turning it
off is deleting one field from the calendar.

NO FONTS. Every renderer that shows these — wallets, marketplaces — puts
the SVG in a sandbox with no network, so a web font simply fails and
silently substitutes. Only the generic families resolve, which is why the
existing card says monospace and why these say serif or sans-serif. The
display faces in the mockups are a later job: an alphabet drawn as paths
and stored once, which is the only way to get identical letterforms on
every device.
*/

// skinFor returns the skin named by whichever calendar rule is active
// today, or "" for the ordinary card. Reusing pickRule means a skin
// obeys the same window rules, the same first-match-wins ordering and
// the same year wrapping as every other season.
func skinFor(now int64) string {
	return skinFromSpec(nsdata.GetGlobal(keyFX), now)
}

// Split out so the calendar logic can be tested against a spec directly,
// without standing up a vault to hold one.
func skinFromSpec(spec string, now int64) string {
	rule := pickRule(spec, now)
	if rule == "" {
		return ""
	}
	return ruleField(rule, "skin")
}

// hasSkin reports whether a name is renderable as this skin. Unknown
// names render nothing rather than a broken card — the same defensive
// stance the overlay parser takes, and for the same reason: this markup
// lands inside a token that other people's software renders.
func hasSkin(name string) bool {
	switch name {
	case "pizza", "paper", "cal", "fog", "slash", "pi", "heart":
		return true
	}
	return false
}

// seedOf turns a token id into a small number, so that a card can differ
// from the one beside it without any randomness — which a deterministic
// machine does not have. Every node computes the same answer for the same
// name, which is the requirement; looking arbitrary is merely the effect.
func seedOf(tid string) int {
	h := 2166136261
	for i := 0; i < len(tid); i++ {
		h ^= int(tid[i])
		h *= 16777619
		h &= 0x7fffffff
	}
	return h
}

// skinSVG renders a complete 400x400 card. Same frame as the ordinary
// one, so nothing downstream has to know which it received.
func skinSVG(name, tid string, now int64) string {
	label := tid
	if at := strings.Index(tid, "*"); at > 0 {
		label = tid
	}
	size := 34
	if len(label) > 14 {
		size = 22
	} else if len(label) > 10 {
		size = 27
	}
	switch name {
	case "pizza":
		return skinPizza(label, size, seedOf(tid))
	case "paper":
		return skinPaper(label, size, now)
	case "cal":
		return skinCal(label, size)
	case "fog":
		return skinFog(label, size)
	case "slash":
		return skinSlash(label, size)
	case "pi":
		return skinPi(label, size)
	case "heart":
		return skinHeart(label, size)
	}
	return ""
}

func head(bg string) string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">` +
		`<rect width="400" height="400" fill="` + bg + `"/>`
}

func foot() string {
	return `<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#ffffff" opacity="0.45">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 22 May: the pizza ----------------
 *
 * Eight wedges with a gap between them, so it reads as CUT rather than
 * merely divided, and each wedge carries its own toppings inside its own
 * group — that is what makes a slice leave with its pepperoni still on
 * it instead of leaving them floating over the board.
 *
 * EVERY NAME EATS IN ITS OWN ORDER. The seed decides which slice goes
 * first and how long each one waits, so a marketplace full of these is a
 * room full of pizzas being eaten from different sides at different
 * rates rather than one animation repeated. It is derived from the token
 * id, so it is the same on every node and different for every name.
 */
func skinPizza(label string, size, seed int) string {
	var b strings.Builder
	b.WriteString(head("#2a2018"))
	b.WriteString(`<circle cx="200" cy="200" r="168" fill="#3a2c20"/>`)

	order := make([]int, 8)
	for i := range order {
		order[i] = i
	}
	// A deterministic shuffle: the seed walks the list and swaps.
	s := seed
	for i := 7; i > 0; i-- {
		s = (s*1103515245 + 12345) & 0x7fffffff
		j := s % (i + 1)
		order[i], order[j] = order[j], order[i]
	}

	for pos, idx := range order {
		a0 := float64(idx)*45 + 1.8
		a1 := float64(idx+1)*45 - 1.8
		// Each slice waits a little longer than the last, with the gap
		// itself varying by name so two cards never keep step.
		begin := 3 + pos*3 + (seed>>uint(pos))%4
		b.WriteString(`<g>`)
		b.WriteString(`<animate attributeName="opacity" values="1;1;0" keyTimes="0;0.5;1"`)
		b.WriteString(ufmt.Sprintf(` dur="%ds" begin="%ds" fill="freeze"/>`, 2, begin))
		b.WriteString(wedge(200, 200, 162, a0, a1, "#d9822b"))
		b.WriteString(wedge(200, 200, 143, a0+1.2, a1-1.2, "#f0b23c"))
		// Three toppings inside this wedge: one pepperoni, two herbs.
		for t := 0; t < 3; t++ {
			s = (s*1103515245 + 12345) & 0x7fffffff
			ang := a0 + 4 + float64(s%int(a1-a0-8))
			s = (s*1103515245 + 12345) & 0x7fffffff
			rad := 46 + float64(s%86)
			x, y := polar(200, 200, rad, ang)
			if t == 0 {
				b.WriteString(ufmt.Sprintf(`<circle cx="%d" cy="%d" r="13" fill="#b8342a"/>`, x, y))
			} else {
				b.WriteString(ufmt.Sprintf(
					`<rect x="%d" y="%d" width="13" height="13" rx="3" fill="#4e8b3a"/>`, x-6, y-6))
			}
		}
		b.WriteString(`</g>`)
	}
	b.WriteString(ufmt.Sprintf(
		`<text x="200" y="212" text-anchor="middle" font-family="sans-serif" font-size="%d"`+
			` font-weight="bold" fill="#2a1405">%s</text>`, size, esc(label)))
	b.WriteString(foot())
	return b.String()
}

func wedge(cx, cy int, r float64, a0, a1 float64, fill string) string {
	x0, y0 := polar(cx, cy, r, a0)
	x1, y1 := polar(cx, cy, r, a1)
	return ufmt.Sprintf(`<path d="M%d %d L%d %d A%d %d 0 0 1 %d %d Z" fill="%s"/>`,
		cx, cy, x0, y0, int(r), int(r), x1, y1, fill)
}

// Degrees clockwise from twelve o'clock, which is how a pizza is cut.
// Integer maths throughout: a realm has no floating point worth trusting
// across nodes, and a pizza does not need sub-pixel accuracy.
func polar(cx, cy int, r float64, deg float64) (int, int) {
	rad := (deg - 90) * 3.14159265 / 180
	return cx + int(r*cosApprox(rad)), cy + int(r*sinApprox(rad))
}

func sinApprox(x float64) float64 {
	for x > 3.14159265 {
		x -= 6.2831853
	}
	for x < -3.14159265 {
		x += 6.2831853
	}
	x2 := x * x
	return x * (1 - x2/6 + x2*x2/120 - x2*x2*x2/5040)
}

func cosApprox(x float64) float64 { return sinApprox(x + 1.5707963) }

/* ---------------- 3 Jan: the front page ---------------- */
func skinPaper(label string, size int, now int64) string {
	year := time.Unix(now, 0).UTC().Year()
	return head("#f4f0e4") +
		`<text x="200" y="66" text-anchor="middle" font-family="serif" font-size="30"` +
		` font-weight="bold" fill="#141210">THE LEDGER</text>` +
		`<line x1="40" y1="80" x2="360" y2="80" stroke="#141210" stroke-width="2"/>` +
		ufmt.Sprintf(`<text x="200" y="100" text-anchor="middle" font-family="monospace"`+
			` font-size="11" fill="#5a5348">3 JANUARY %d &#183; BLOCK ZERO</text>`, year) +
		ufmt.Sprintf(`<text x="200" y="176" text-anchor="middle" font-family="serif"`+
			` font-size="%d" font-weight="bold" fill="#141210">%s</text>`, size+6, esc(label)) +
		`<text x="200" y="214" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">The first block is mined. A chain begins.</text>` +
		`<text x="200" y="234" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">Years later somebody registers a name</text>` +
		`<text x="200" y="254" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">on it that does nothing at all.</text>` +
		`<line x1="40" y1="278" x2="360" y2="278" stroke="#b9b2a2" stroke-width="1"/>` +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#5a5348">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 29 Feb: the calendar page ---------------- */
func skinCal(label string, size int) string {
	return head("#ffffff") +
		`<rect width="400" height="72" fill="#c0392b"/>` +
		`<text x="200" y="49" text-anchor="middle" font-family="sans-serif" font-size="26"` +
		` font-weight="bold" fill="#ffffff" letter-spacing="6">FEBRUARY</text>` +
		`<circle cx="150" cy="24" r="9" fill="#f7f4ee" stroke="#00000055" stroke-width="3"/>` +
		`<circle cx="250" cy="24" r="9" fill="#f7f4ee" stroke="#00000055" stroke-width="3"/>` +
		`<text x="200" y="252" text-anchor="middle" font-family="sans-serif" font-size="170"` +
		` font-weight="bold" fill="#e8e3d9">29</text>` +
		ufmt.Sprintf(`<text x="200" y="300" text-anchor="middle" font-family="monospace"`+
			` font-size="%d" font-weight="bold" fill="#1a1a1a">%s</text>`, size, esc(label)) +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#8a857a">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 20 Apr: the fog ---------------- */
func skinFog(label string, size int) string {
	return head("#1d4028") +
		`<defs><radialGradient id="g"><stop offset="0" stop-color="#8fd48a"/>` +
		`<stop offset="0.68" stop-color="#3f7a4a"/><stop offset="1" stop-color="#1d4028"/>` +
		`</radialGradient><filter id="b"><feGaussianBlur stdDeviation="26"/></filter></defs>` +
		`<rect width="400" height="400" fill="url(#g)"/>` +
		`<g filter="url(#b)" opacity="0.5">` +
		`<circle cx="130" cy="140" r="90" fill="#ffffff" opacity="0.5">` +
		`<animate attributeName="cx" values="130;190;130" dur="18s" repeatCount="indefinite"/>` +
		`</circle>` +
		`<circle cx="280" cy="250" r="80" fill="#ffffff" opacity="0.35">` +
		`<animate attributeName="cy" values="250;200;250" dur="22s" repeatCount="indefinite"/>` +
		`</circle></g>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="sans-serif"`+
			` font-size="%d" font-weight="bold" fill="#f2fff2">%s</text>`, size, esc(label)) +
		foot()
}

/* ---------------- Friday 13th: the poster ---------------- */
func skinSlash(label string, size int) string {
	return head("#15080a") +
		`<path d="M88 -20 L112 420 L96 420 L72 -20 Z" fill="#c42c24" opacity="0.85"/>` +
		`<path d="M252 420 L268 -20 L278 -20 L262 420 Z" fill="#8e1d18" opacity="0.7"/>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="serif"`+
			` font-size="%d" font-weight="bold" fill="#d8342c">%s</text>`, size+4, esc(label)) +
		foot()
}

/* ---------------- 14 Mar: pi ---------------- */
func skinPi(label string, size int) string {
	digits := []string{
		"3.14159265358979323846", "26433832795028841971", "69399375105820974944",
		"59230781640628620899", "86280348253421170679", "82148086513282306647",
	}
	var b strings.Builder
	b.WriteString(head("#101418"))
	for i, row := range digits {
		b.WriteString(ufmt.Sprintf(
			`<text x="26" y="%d" font-family="monospace" font-size="30" fill="#2b4756">%s</text>`,
			70+i*56, row))
	}
	b.WriteString(`<rect x="52" y="176" width="296" height="52" rx="8" fill="#101418"/>`)
	b.WriteString(ufmt.Sprintf(
		`<text x="200" y="212" text-anchor="middle" font-family="monospace" font-size="%d"`+
			` font-weight="bold" fill="#eaf2f6">%s</text>`, size, esc(label)))
	b.WriteString(foot())
	return b.String()
}

/* ---------------- 14 Feb: the heart ----------------
 *
 * A real double thump, not one pulse: squeeze, small recoil, second
 * smaller squeeze, then a long rest. The rest is most of what makes it
 * read as a heartbeat rather than a throb.
 */
func skinHeart(label string, size int) string {
	return head("#fbe3ec") +
		`<g transform="translate(200,196)">` +
		`<animateTransform attributeName="transform" type="scale"` +
		` values="1;1.085;0.995;1.05;1;1" keyTimes="0;0.09;0.18;0.27;0.40;1"` +
		` dur="1.15s" repeatCount="indefinite" additive="sum"/>` +
		`<path transform="translate(-150,-140)" fill="#f7c3d5" stroke="#e39bb5" stroke-width="5"` +
		` d="M150 258 C66 198 24 150 24 102 A60 60 0 0 1 150 72 A60 60 0 0 1 276 102` +
		` C276 150 234 198 150 258 Z"/></g>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="sans-serif"`+
			` font-size="%d" font-weight="bold" fill="#7e1f3d" letter-spacing="2">%s</text>`,
			size, esc(strings.ToUpper(label))) +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#b03a62" opacity="0.7">MINTED ON GNO.LAND</text></svg>`
}

// Markup safety, same as everywhere else that puts a name into SVG: a
// label is validated on registration, but this is the last gate before
// it lands inside somebody else's renderer.
func esc(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

package nsview

import (
	"encoding/base64"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

// The NFT artwork and every piece of display formatting live here, in a
// realm that can be redeployed, rather than in the vault that cannot.
// nsdata.TokenURI points at this realm through a settable prefix.

// TokenURI returns the full data: URI for a token, generated on every
// read so the image always reflects current state (never baked at mint).
func TokenURI(tid string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(BuildSVG(tid)))
}

// BuildSVG renders a token. Everything on the card derives from four
// stored values — owner, registered, expires, and the domain's drawing —
// so a renewal moves `expires` and the bar, the time remaining and the
// years held all follow from it. Nothing is baked at mint: the card is
// generated on every read, which is what lets a domain's artwork be
// changed after its names have been sold.
func BuildSVG(tid string) string {
	var registered, expires int64 // unix seconds
	var streak int64
	var frozen bool
	var domainLabel string

	if strings.HasPrefix(tid, "*") {
		label := tid[1:]
		if !nsdata.DomainExists(label) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen = nsdata.GetDomainInfo(label)
		domainLabel = label
	} else {
		label, dom := splitTokenID(tid)
		if !nsdata.NameExists(label, dom) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen, _ = nsdata.GetNameInfo(label, dom)
		domainLabel = dom
	}

	now := time.Now().Unix()
	// The three vault reads happen HERE, not inside cardSVG. That is what
	// leaves the card itself a pure function of its inputs, which is what
	// lets a test assert what a marketplace will show without standing up
	// a registry to do it.
	// A SKIN REPLACES THE CARD, so it is decided before anything is read
	// from the vault for drawing one. The ordinary path is untouched on
	// every other day of the year.
	if sk := skinFor(now); sk != "" && hasSkin(sk) {
		return skinSVG(sk, tid, now)
	}

	art := nsdata.GetDomainExtra(domainLabel, keyArt)
	return cardSVG(tid, art, registered, expires, streak, frozen, now, overlaySVG(now))
}

// cardSVG is the card itself, with every stored value already resolved.
// Split out from BuildSVG so the markup can be rendered — and asserted
// against — without a vault under it. TestStaticFrameShowsTheDate is the
// reason: what a marketplace shows as a still is a property of this
// string and of nothing else, and it deserves to be checked rather than
// assumed.
func cardSVG(tid, art string, registered, expires, streak int64, frozen bool, now int64, overlay string) string {
	accent := accentOf(art)
	status, edge := statusFields(expires, frozen)

	// The ribbon says something the rest of the card does not.
	// "DIAMOND HANDS" on a name minted this morning is a joke that lands
	// once; tied to tenure it is a thing you get TO.
	ribbon := status
	if status == "LIVE" {
		if streak >= 1 {
			ribbon = "DIAMOND HANDS"
		} else {
			ribbon = "FIRST YEAR"
		}
	}

	// The domain's drawing as a wash, centred: twelve cells at 26px is
	// 312 wide, so 44px of margin on every side.
	//
	// 0.07, not 0.12. At 0.12 a bright sprite competed with the name
	// sitting on top of it — the eye landed on the picture first and had
	// to hunt for the type. A wash should be felt rather than read.
	wash := spriteSVG(art, 26, 44, 44, "0.07")

	// The bar is the whole term, filled by how much of it is left.
	span := expires - registered
	if span < 1 {
		span = 1
	}
	left := expires - now
	if left < 0 {
		left = 0
	}
	if left > span {
		left = span
	}
	fill := (308 * left) / span

	heldLabel := "YEARS HELD"
	if streak == 1 {
		heldLabel = "YEAR HELD"
	}

	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">
  <rect width="400" height="400" fill="#10101a"/>
  %s
  <rect x="12" y="12" width="376" height="376" rx="18" fill="none" stroke="%s" stroke-width="3"/>
  <text x="30" y="42" font-family="monospace" font-size="10" fill="%s" opacity="0.7">MINTED ON GNO.LAND</text>
  <text x="370" y="42" text-anchor="end" font-family="monospace" font-size="10" fill="%s" opacity="0.7">SINCE %s</text>
  <text x="200" y="196" text-anchor="middle" font-family="monospace" font-size="%d" font-weight="bold" fill="#ffffff">%s</text>
  <!-- THE STATIC FRAME. A marketplace showing this token as a still
       gets whichever of these two lines is visible with no animation
       running, and that MUST be the date. Everything that matters about
       a name at a glance -- is it live, is it expired, when does it go
       -- is in the date; "412 days left" frozen into a thumbnail is a
       number that was true once and is a lie thereafter.

       It works out that way under both kinds of renderer, which is why
       it is written like this and not any other way:

         a renderer that IGNORES SMIL uses the base attribute in the
         markup, so the date's opacity="1" and the counter's opacity="0"
         decide it

         a renderer that HONOURS SMIL and seeks to t=0 uses the first
         keyTime, so the date's values="1;0" and the counter's "0;1"
         decide it

       Both must keep agreeing. Reorder these two lines, or drop an
       explicit opacity, and the still becomes a countdown -- with
       nothing failing and nothing to notice until a card in somebody
       else's gallery says a name has 412 days left three years from
       now. Guarded by TestStaticFrameShowsTheDate. -->
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="1">%s<animate attributeName="opacity" calcMode="discrete" values="1;0" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="0">%s<animate attributeName="opacity" calcMode="discrete" values="0;1" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <rect x="46" y="256" width="308" height="9" rx="4" fill="#ffffff" opacity="0.13"/>
  <rect x="46" y="256" width="%d" height="9" rx="4" fill="%s"/>
  <text x="46" y="282" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="354" y="282" text-anchor="end" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="200" y="326" text-anchor="middle" font-family="monospace" font-size="30" font-weight="bold" fill="#ffffff">%d</text>
  <text x="200" y="344" text-anchor="middle" font-family="monospace" font-size="9" fill="%s" opacity="0.8">%s</text>
  <text x="200" y="372" text-anchor="middle" font-family="monospace" font-size="12" font-weight="bold" fill="%s">%s</text>
  %s
</svg>`,
		wash, edge,
		accent, accent, time.Unix(registered, 0).UTC().Format("2006"),
		fitSize(tid), escapeXML(tid),
		accent, time.Unix(expires, 0).UTC().Format("Jan 2, 2006"),
		accent, remaining(expires, now),
		fill, edge,
		time.Unix(registered, 0).UTC().Format("Jan 2006"),
		time.Unix(expires, 0).UTC().Format("Jan 2006"),
		streak, accent, heldLabel,
		edge, ribbon,
		overlay)
}

// fitSize solves for a size rather than stepping through a ladder.
// Monospace glyphs are ~0.6em, so a name up to the full 32-character
// limit sets on one line without overflowing 336px.
func fitSize(s string) int {
	n := len(s)
	if n < 1 {
		n = 1
	}
	size := 336 * 10 / (6 * n)
	// 40, not 34: the name is the thing somebody bought, and on a card
	// where the drawing sits behind it, the type has to be the loudest
	// object on the tile. Short names were leaving the middle of the card
	// half empty.
	if size > 40 {
		size = 40
	}
	if size < 11 {
		size = 11
	}
	return size
}

// domainAccent reads the accent out of the domain's stored drawing, so
// the card wears the domain's own colour without this realm carrying a
// palette of its own. Falls back to the house colour.
func domainAccent(domainLabel string) string {
	return accentOf(nsdata.GetDomainExtra(domainLabel, keyArt))
}

func accentOf(enc string) string {
	if len(enc) >= 8 && enc[1] == '#' && isHexColour(enc[1:8]) {
		return enc[1:8]
	}
	return "#5eead4"
}

func remaining(expires, now int64) string {
	if now >= expires {
		d := (now - expires) / daySeconds
		if d <= 0 {
			return "expired today"
		}
		if d == 1 {
			return "1 day past due"
		}
		return ufmt.Sprintf("%d days past due", d)
	}
	d := (expires - now) / daySeconds
	if d <= 0 {
		return "expires today"
	}
	if d == 1 {
		return "1 day remaining"
	}
	return ufmt.Sprintf("%d days remaining", d)
}

// keyArt is the per-domain extension key holding the drawing. The value
// is "A#facc15,B#7c2d12|............|....AAAA....|..." — the palette,
// then twelve rows of twelve characters where '.' is transparent.
//
// PARSED DEFENSIVELY AND NEVER TRUSTED. It is written by whichever logic
// realm is current, so a future one could store something malformed;
// anything unexpected yields no sprite rather than broken markup inside
// a token that a marketplace will render.
const keyArt = "art"

func spriteSVG(enc string, px, ox, oy int, opacity string) string {
	if enc == "" {
		return ""
	}
	parts := strings.Split(enc, "|")
	if len(parts) != 13 {
		return ""
	}
	// palette: "A#facc15,B#7c2d12"
	colours := map[string]string{}
	for _, entry := range strings.Split(parts[0], ",") {
		// key + "#" + six hex digits: "A#facc15" is EIGHT characters.
		// This read 7 and rejected every valid sprite; the test caught it.
		if len(entry) != 8 || entry[1] != '#' {
			return ""
		}
		key := entry[:1]
		hex := entry[1:]
		if !isHexColour(hex) {
			return ""
		}
		colours[key] = hex
	}
	var b strings.Builder
	for y := 1; y <= 12; y++ {
		row := parts[y]
		if len(row) != 12 {
			return ""
		}
		for x := 0; x < 12; x++ {
			ch := row[x : x+1]
			if ch == "." {
				continue
			}
			c, ok := colours[ch]
			if !ok {
				return ""
			}
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`,
				ox+(x*px), oy+((y-1)*px), px, px, c))
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return `<g opacity="` + opacity + `">` + b.String() + `</g>`
}

func isHexColour(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < 7; i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

func placeholderSVG(msg string) string {
	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`+
		`<rect width="400" height="400" fill="#10101a"/>`+
		`<text x="200" y="200" text-anchor="middle" font-family="monospace" font-size="18" fill="#666680">%s</text></svg>`,
		escapeXML(msg))
}

// statusFields formats a lifecycle state for display. Reads the grace
// period from nsdata rather than hardcoding it, so retuning the lifecycle
// is a config change and this stays correct.
// All lifecycle times are unix seconds, so this is integer arithmetic
// over a day constant rather than duration division.
const daySeconds = int64(24 * 60 * 60)

func statusFields(expires int64, frozen bool) (status, edge string) {
	if frozen {
		return "FROZEN", "#8888aa"
	}
	now := time.Now().Unix()
	grace := nsdata.GetGracePeriod()
	switch {
	case now < expires:
		return "LIVE", "#4ade80"
	case now < expires+grace:
		return "GRACE PERIOD", "#facc15"
	default:
		return "LAPSED", "#f87171"
	}
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

package nsskin

import (
	"gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

func nameKey(label, domain string) string { return domain + "*" + label }

// grcID saves every call site from importing grc721 just to cast.
func grcID(tid string) grc721.TokenID { return grc721.TokenID(tid) }

/*
Attach binds a skin to a name and puts the token into this realm's
custody. See the long note in types.gno for why custody rather than a
lock in place: it is what makes a marketplace's escrow of the NAME
irrelevant to the skin.

ONE SKIN, ONE NAME, both ways. A token may be attached to one name, and
a name may wear one skin. Letting one copy dress every name a person owns
would make the second copy pointless, and the object stops meaning
anything.
*/
func Attach(cur realm, tid, label, domain string) {
	assertNoSend(cur)
	wear(cur, tid, label, domain, cur.Previous().Address())
}

// wear is Attach's body, shared with Buy so that buying and wearing
// settle in one transaction. Splitting them would let a buyer stop
// halfway and end up holding a skin they paid for and did not put on.
func wear(cur realm, tid, label, domain string, caller address) {
	id, ok := skinOfToken(tid)
	if !ok {
		panic("nsskin: no such skin token: " + tid)
	}
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and cannot be worn")
	}
	if bound.Has(tid) {
		panic("nsskin: " + tid + " is already on a name — claim it back first")
	}
	if nameBound.Has(nameKey(label, domain)) {
		panic("nsskin: " + label + "*" + domain + " already wears a skin")
	}

	owner, err := nft.OwnerOf(grcID(tid))
	if err != nil {
		panic("nsskin: " + err.Error())
	}
	if owner != caller {
		panic("nsskin: you do not own " + tid)
	}

	if !nsdata.NameExists(label, domain) {
		panic("nsskin: no such name: " + label + "*" + domain)
	}
	if !nsdata.IsNameValid(label, domain) {
		panic("nsskin: " + label + "*" + domain + " has expired")
	}
	nameOwner, registered, _, _, _, _ := nsdata.GetNameInfo(label, domain)
	if nameOwner != caller {
		panic("nsskin: you do not own " + label + "*" + domain)
	}
	if s.lock != "" && s.lock != domain {
		panic(ufmt.Sprintf("nsskin: %s only goes on *%s names, not *%s", id, s.lock, domain))
	}

	// Into custody. From here the token is in nobody's wallet, so it
	// cannot be listed anywhere or sold out from under the name.
	if err := nft.TransferFrom(caller, caller, cur.Address(), grcID(tid)); err != nil {
		panic("nsskin: could not take custody: " + err.Error())
	}
	bound.Set(tid, &binding{label: label, domain: domain, registered: registered, binder: caller})
	nameBound.Set(nameKey(label, domain), tid)
}

/*
Refresh points a binding's `binder` at the name's CURRENT owner.

WHY THIS EXISTS, and it is the fix for a real hole. `binder` decides who
gets the skin back once the name record is gone. Set once at Attach and
never updated, it names whoever ATTACHED the skin — so: Alice attaches,
sells the name to Bob, the skin travels with it as intended, Bob lets the
name lapse, and the skin goes back to ALICE. Bob paid for it. That is
not a limitation, it is taking something from the person who bought it.

nsdata cannot tell us a name changed hands — it is permanent, it has no
hook, and it never will. So `binder` cannot be maintained; it can only be
CAUGHT UP. This is that, and it is deliberately open to anyone:

	it only ever writes the name's real current owner, so calling it can
	never move the skin anywhere it should not go, and there is nothing
	to gain by calling it on somebody else's binding

	which means the site can call it on a purchase, a keeper can call it
	on a schedule, the buyer can call it themselves, or nobody calls it
	at all and the next Attach or Claim does it — all with the same
	result and none of them needing to be trusted

Nothing on chain is automatic here. gno has no scheduler and nsdata has
no callback, so every version of "the skin follows the sale" is one extra
call by someone. Making that call safe for ANYONE to make is as close to
automatic as this can get, and it is close enough.
*/
func Refresh(cur realm, tid string) {
	v := bound.Get(tid)
	if v == nil {
		return
	}
	b := v.(*binding)
	if !nsdata.NameExists(b.label, b.domain) {
		return
	}
	owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
	// Only for THIS registration. If the name lapsed and somebody else
	// took it, the current owner is a stranger to this binding and must
	// not be recorded as entitled to anything.
	if registered != b.registered {
		return
	}
	b.binder = owner
}

// refresh is Refresh without the realm ceremony, for the callers below.
func refresh(b *binding) {
	if !nsdata.NameExists(b.label, b.domain) {
		return
	}
	owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
	if registered != b.registered {
		return
	}
	b.binder = owner
}

/*
Claim takes a skin out of custody and into the caller's wallet.

WHO MAY, and this is the whole travels-with-the-name rule:

	the CURRENT OWNER of the name, while the name record still exists.
	Buy the name, claim the skin — including a name bought from someone
	else, which is the point.

	the LAST KNOWN NAME OWNER, once the record is gone entirely. That is
	the "it comes back to your wallet when the name expires" case — and
	"last known" rather than "whoever attached it", because after a sale
	those are different people and only one of them paid for it. See
	Refresh above for how that is kept current without a hook nsdata
	does not have.

The binding is pinned to one REGISTRATION. If a name lapsed and somebody
else registered it, its timestamp has changed, so the new registrant is
not the owner of anything here and cannot claim.
*/
func Claim(cur realm, tid string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	v := bound.Get(tid)
	if v == nil {
		panic("nsskin: " + tid + " is not on a name")
	}
	b := v.(*binding)

	// Catch `binder` up before deciding, so a name that changed hands
	// since it was attached settles on the person who holds it now
	// rather than the person who first attached it.
	refresh(b)

	entitled := false
	if nsdata.NameExists(b.label, b.domain) {
		owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
		if registered == b.registered {
			// A live binding: the name's owner controls the skin.
			entitled = owner == caller
		} else {
			// The name lapsed and was taken by somebody else. Whatever
			// they own, it is not this.
			entitled = caller == b.binder
		}
	} else {
		// The record is gone. Back to whoever put it there.
		entitled = caller == b.binder
	}
	if !entitled {
		panic("nsskin: " + tid + " belongs to " + b.label + "*" + b.domain +
			", and you are neither its owner nor the person who attached this")
	}

	if err := nft.TransferFrom(cur.Address(), cur.Address(), caller, grcID(tid)); err != nil {
		panic("nsskin: could not release: " + err.Error())
	}
	bound.Remove(tid)
	// Only clear the reverse entry if it still points at THIS token — a
	// stale binding may have been superseded by a new registrant's own
	// skin, and clearing it blindly would strip theirs.
	if cur := nameBound.Get(nameKey(b.label, b.domain)); cur != nil && cur.(string) == tid {
		nameBound.Remove(nameKey(b.label, b.domain))
	}
}

// SkinOnName returns the token currently worn by a name, or "".
func SkinOnName(label, domain string) string {
	v := nameBound.Get(nameKey(label, domain))
	if v == nil {
		return ""
	}
	return v.(string)
}

// BindingOf reports where a token is attached, for a wallet or a shop.
func BindingOf(tid string) (label, domain string, registered int64, binder address) {
	v := bound.Get(tid)
	if v == nil {
		return "", "", 0, ""
	}
	b := v.(*binding)
	return b.label, b.domain, b.registered, b.binder
}

package nsskin

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

const ugnot = "ugnot"

/*
BUYING ONE, AND WEARING IT, IN A SINGLE TRANSACTION.

Splitting these would mean a buyer signs twice and can stop between —
leaving a skin they paid for sitting unworn in a wallet, which is the
state nobody wants and the one a two-step flow produces most often. So
the name is an argument: pass it and the skin is minted and attached
together; pass "" and it is minted loose, which is what somebody buying
ahead of registering a name needs.

NOTHING IS EVER HELD. Payment, treasury and refund all settle inside the
buyer's own transaction, exactly as nslogic does it — and for the same
reason, which is worth restating because it is a legal position rather
than a style: a realm you can have a BALANCE in is a different kind of
thing to operate, subject to different rules, run by people with
licences. Every ugnot that arrives leaves again in the same call.

THE 70/30 SPLIT IS NOT HERE, and that is deliberate rather than
forgotten. Every skin in this collection is ours, so the artist and the
treasury are the same address and a split would move money from a
pocket to itself while costing gas to do it. The artist is recorded on
every definition so the day it stops being us, this is where the split
goes — see SKINS.md.
*/
func Buy(cur realm, id, label, domain string) string {
	if !cur.Previous().IsUserCall() {
		panic("nsskin: only direct wallet calls may attach payment")
	}
	buyer := cur.Previous().Address()
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and is not for sale")
	}
	// Refuse the sale rather than the attach. Minting a locked skin to
	// somebody who wanted it for a name it will never go on is a refund
	// request wearing the clothes of a successful purchase.
	if label != "" && s.lock != "" && s.lock != domain {
		panic(ufmt.Sprintf("nsskin: %s only goes on *%s names, not *%s", id, s.lock, domain))
	}

	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nsskin: only ugnot is accepted, got: " + c.Denom)
		}
	}
	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nsskin: insufficient payment: need %d ugnot, got %d", price, paid))
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	me := cur.Address()
	if price > 0 {
		b.SendCoins(me, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price)})
	}
	if excess := paid - price; excess > 0 {
		b.SendCoins(me, buyer, chain.Coins{chain.NewCoin(ugnot, excess)})
	}

	s.minted++
	tid := ufmt.Sprintf("%s#%d", id, s.minted)
	if err := nft.Mint(buyer, grcID(tid)); err != nil {
		panic("nsskin: mint failed: " + err.Error())
	}
	tokenSkin.Set(tid, id)

	if label != "" {
		wear(cur, tid, label, domain, buyer)
	}
	return tid
}

// SetPrice is in ugnot, because that is what the chain moves. What it is
// worth in anything else is a question for the page that quotes it, and
// pinning a dollar figure into a contract that cannot see an exchange
// rate would be a lie with a number in it.
func SetPrice(cur realm, p int64) {
	assertIsAdmin(cur)
	if p < 0 {
		panic("nsskin: a negative price is not a discount")
	}
	price = p
}

func GetPrice() int64 { return price }

// Free calls must not be able to strand coins here. This realm has no
// withdrawal path, so anything attached to one would sit in its address
// permanently.
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return
	}
	if len(unsafe.OriginSend()) > 0 {
		panic("nsskin: this call takes no payment")
	}
}

package nsskin

import "gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"

// The deployer is the first admin. Rotatable with SetAdmin, and
// deliberately NOT the vault's timelocked governance: this realm is
// replaceable, so it does not need machinery built for one that is not.
// See the note in types.gno.
func init(cur realm) {
	nft = grc721.NewBasicNFT(0, cur, "Meme Name Service Skins", "MNSKIN")
	admin = cur.Previous().Address()
}

package nsskin

import (
	"strings"

	"gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v1"
)

/*
ArtForName is the one question the renderer asks, and it is answered here
so the rule lives with the data it depends on.

It returns the sprite a name should be drawn with, or "" for the ordinary
card. Everything the renderer would otherwise have to remember to check
is inside it, because a renderer that has to remember three things before
drawing is one that eventually forgets one.

The checks, and what each of them makes self-cleaning:

	the name wears a token at all
	that token's definition has not been WITHDRAWN — so a takedown
	  reverts every name wearing it, everywhere, at once, with no
	  migration and no per-name cleanup
	the binding is FRESH, pinned to this registration — so a name that
	  lapsed and was taken by somebody else inherits nothing
	the LOCK still matches — belt and braces, since Attach checks it too

Note what is NOT checked: who holds the token in their wallet. Nobody
does. It is in this realm's custody for as long as it is attached, which
is what makes the skin travel with the name instead of with a wallet.
*/
func ArtForName(label, domain string) string {
	tid := SkinOnName(label, domain)
	if tid == "" {
		return ""
	}
	v := bound.Get(tid)
	if v == nil {
		return ""
	}
	b := v.(*binding)

	if !nsdata.NameExists(label, domain) {
		return ""
	}
	_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domain)
	if registered != b.registered {
		return "" // a different registration of the same label
	}

	id, ok := skinOfToken(tid)
	if !ok {
		return ""
	}
	sv := skins.Get(id)
	if sv == nil {
		return ""
	}
	s := sv.(*skin)
	if s.withdrawn {
		return ""
	}
	if s.lock != "" && s.lock != domain {
		return ""
	}
	return s.art
}

// SkinInfo describes a DEFINITION, for a shop listing or a skin's own
// card. Withdrawn is returned rather than hidden: a holder is entitled
// to know, and a listing that silently vanishes is worse than one that
// says what happened.
func SkinInfo(id string) (name, art, lock string, artist address, withdrawn bool, minted int64) {
	s := mustSkin(id)
	return s.name, s.art, s.lock, s.artist, s.withdrawn, s.minted
}

func SkinExists(id string) bool {
	return skins.Has(strings.ToLower(strings.TrimSpace(id)))
}

// ListSkins returns every definition id, in tree order. Small by
// construction — this is a curated shop, not a submission firehose — and
// if that ever stops being true it wants paging rather than a bigger
// answer.
func ListSkins() []string {
	var out []string
	skins.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

/*
AllSkins packs the whole catalogue into ONE read.

A shop page needs every definition's name, lock and availability, and
asking for them one at a time is sixty round trips before anything
appears on screen. The ART is deliberately NOT here: it is the bulk of
the data, it is committed in the repo as the canonical source, and a
page that already has it does not need to fetch it again.

Tab-separated fields, newline-separated records — not JSON, because
building JSON by string concatenation in a realm is how quoting bugs get
shipped, and a shop is not worth that risk. No field can contain a tab
or a newline: ids and locks are [a-z0-9-] by rule, and a name is checked
here rather than assumed.
*/
func AllSkins() string {
	var b strings.Builder
	skins.Iterate("", "", func(k string, v any) bool {
		s := v.(*skin)
		nm := s.name
		if strings.ContainsAny(nm, "\t\n") {
			nm = "?" // never seen: DefineSkin would have to have accepted it
		}
		w := "0"
		if s.withdrawn {
			w = "1"
		}
		b.WriteString(k + "\t" + nm + "\t" + s.lock + "\t" + w + "\t" +
			ufmt.Sprintf("%d", s.minted) + "\n")
		return false
	})
	return b.String()
}

func skinOfToken(tid string) (string, bool) {
	v := tokenSkin.Get(tid)
	if v == nil {
		return "", false
	}
	return v.(string), true
}

// SkinOfToken is skinOfToken for callers outside the realm.
func SkinOfToken(tid string) string {
	id, _ := skinOfToken(tid)
	return id
}

func GetAdmin() address        { return admin }
func GetTokenURIBase() string  { return tokenURIBase }
func IsTrustedShop(a address) bool {
	return trustedShop.Has(a.String())
}

// ---------------------------------------------------------------- grc721

func Name() string      { return nft.Name() }
func Symbol() string    { return nft.Symbol() }
func TokenCount() int64 { return nft.TokenCount() }

func BalanceOf(owner address) int64 {
	bal, err := nft.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf does NOT hide a withdrawn skin's owner, and that is the
// opposite of what nsdata does for an expired name.
//
// There, hiding the owner is an anti-scam measure: a lapsed name must
// not be listable, because the seller no longer controls it. Here the
// holder still owns the token completely — withdrawal only stops it
// being DRAWN. Hiding the owner would break transfers and approvals for
// somebody who has done nothing wrong, to solve a problem that is not
// theirs.
func OwnerOf(tid grc721.TokenID) address {
	owner, err := nft.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	return owner
}

func GetApproved(tid grc721.TokenID) address {
	a, err := nft.GetApproved(tid)
	if err != nil {
		panic(err)
	}
	return a
}

func IsApprovedForAll(owner, operator address) bool {
	return nft.IsApprovedForAll(owner, operator)
}

func TokenURI(tid grc721.TokenID) string {
	return tokenURIBase + string(tid)
}

// Package nsskin holds purchasable card art — the skins — as tokens of
// their own, and binds them to names.
//
// WHY THIS IS ITS OWN REALM AND NOT PART OF nsdata. SKINS.md §8 listed
// it as undecided; it is decided here, because the reasoning turned out
// to be one-sided rather than balanced.
//
//	nsdata IS PERMANENT. It cannot be replaced, ever. A second kind of
//	token in it means every mistake in the skin model is permanent too,
//	and the skin model is the newest and least settled thing here.
//
//	nsdata.OwnerOf DELIBERATELY PANICS FOR EXPIRED TOKENS so a lapsed
//	name cannot be listed anywhere. Skins do not expire. That machinery
//	is exactly wrong for them, and a conditional on token kind inside
//	the one realm that can never be fixed is the worst place for it.
//
//	A NEW REALM CAN BE REPLACED while it holds a handful of tokens. The
//	vault cannot, at any point, for any reason.
//
// So being wrong here costs a migration nobody notices. Being wrong
// inside nsdata costs forever.
//
// # A SKIN IS TWO THINGS
//
//	A DEFINITION is the artwork: a name, a sprite, an optional extension
//	lock, and the artist to pay. One per design, stored once — a
//	thousand holders of one design cost one sprite, not a thousand.
//
//	A TOKEN is somebody's copy. Editions are unlimited, because SKINS.md
//	is explicit that a cap is a floor price with extra steps and resale
//	value is never part of the pitch.
//
// # A SKIN BINDS TO ONE NAME, AND TRAVELS WITH IT
//
// This reverses an earlier recommendation of mine, and the new answer is
// better. I had argued for keeping them separate — a pointer from the
// name, reverting on sale — because names expire and skins should not.
// The objection to bundling was that a buyer sees a skinned card on a
// marketplace and receives an unskinned name.
//
// Binding solves that rather than working around it. The skin genuinely
// comes with the name, so the card is not misleading, and the small
// disclosure line the old model needed inside the artwork disappears.
// And a skin still does not die with a name: when the name goes, the
// skin comes back.
//
// # WHY ATTACHING ESCROWS THE TOKEN, WHICH IS THE WHOLE CUSTODY ANSWER
//
// The worry: a name listed on a marketplace that takes CUSTODY. If the
// skin lived in the seller's wallet, a custodial listing would hold the
// name while the skin sat somewhere else, and untangling that on expiry
// would need cooperation we cannot compel.
//
// So attaching moves the token to THIS REALM'S OWN ADDRESS. While
// attached it is in nobody's wallet: it cannot be listed, cannot be sold
// out from under the name, and a marketplace escrowing the NAME never
// touches it. The question of freeing a skin from somebody else's
// custody does not arise, because it was never in it.
//
// Taking it out again is one rule with one fallback:
//
//	WHILE THE NAME EXISTS, its CURRENT OWNER may claim the skin. That is
//	what makes it travel: buy the name, claim the skin.
//
//	IF THE NAME RECORD IS GONE — lapsed and reclaimed — whoever attached
//	it may take it back, which is the "it returns to your wallet" case.
//
// One limitation, stated rather than hidden: buy a name with a skin,
// never claim it, and let that name lapse completely, and the skin
// returns to whoever attached it. Claiming on purchase avoids it
// entirely, and the site prompts for exactly that.
package nsskin

import (
	"gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"
	"gno.land/p/nt/avl/v0"
)

type skin struct {
	name   string // as the shop shows it
	art    string // the sprite string, in the format nsview parses
	lock   string // an extension label, or "" for one that goes anywhere
	artist address
	// WITHDRAWN IS NOT DELETED, and the distinction is the whole
	// takedown mechanism (SKINS.md §6). Deleting a definition orphans
	// every token pointing at it. Withdrawing leaves everything in place
	// and stops it drawing — every name wearing it reverts at once, with
	// no migration and no per-name cleanup, because the card is
	// generated on every read.
	withdrawn bool
	minted    int64 // how many copies exist, and the next serial
}

// A live attachment. `registered` pins it to one REGISTRATION of the
// name, not to the label: if the name lapses and somebody else takes it,
// the timestamp changes and this binding is stale, so the new registrant
// inherits nothing.
type binding struct {
	label      string
	domain     string
	registered int64
	binder     address // who attached it, and who gets it back if the name dies
}

var (
	// Constructed in init, which is where it can be handed the realm.
	nft   *grc721.BasicNFT
	skins = avl.NewTree() // definition id -> *skin

	// token id -> definition id. Derivable by splitting the token id,
	// but stored so a lookup is a tree read rather than string surgery
	// that has to agree with the minter forever.
	tokenSkin = avl.NewTree()

	bound     = avl.NewTree() // token id      -> *binding
	nameBound = avl.NewTree() // "domain*label" -> token id

	// Whichever realm renders a skin card. Same reasoning as nsdata's:
	// the art is the most cosmetic and most-likely-to-be-revised thing
	// here, so it must not be frozen into a token contract.
	tokenURIBase = "/r/demo/nsview:skin/"

	// Day-to-day authority: define, mint, withdraw. Deliberately a plain
	// address rather than the vault's timelocked governance — this realm
	// is replaceable, so it does not need machinery built for one that
	// is not.
	admin address

	// Realms allowed to mint on somebody's behalf, which is what a shop
	// is. Empty at first: the launch batch is minted by the admin.
	trustedShop = avl.NewTree()

	// What one costs, in ugnot. Zero until an admin sets it, so a
	// misconfigured deploy gives skins away rather than charging an
	// accidental amount — the failure that costs nobody money.
	price int64
)

const (
	maxSkinName = 40
	maxSkinArt  = 2048 // a 32x32 sprite is about 1,100 bytes
	maxSkinID   = 24   // appears in every token id and every binding
)

package nsskin

import (
	"strings"

	"gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"
	"gno.land/p/nt/ufmt/v0"
)

func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("nsskin: not the admin")
	}
}

func assertIsAdminOrShop(cur realm) {
	a := cur.Previous().Address()
	if a == admin {
		return
	}
	if !trustedShop.Has(a.String()) {
		panic("nsskin: not the admin or a trusted shop")
	}
}

/*
DefineSkin registers a design. It does not mint anything.

Definitions and copies are separate calls on purpose: defining is the
expensive, careful, one-off act that puts an artist's work and a sprite
on chain, while minting is the cheap repeated one. Rolling them together
would mean re-sending the artwork with every sale.

A definition may be REDEFINED only while nothing has been minted from it.
After the first copy exists, the art is what its holders bought and it
stops being ours to edit — the only lever left is withdrawal, which is
honest about what it is doing.
*/
func DefineSkin(cur realm, id, name, art, lock string, artist address) {
	assertIsAdmin(cur)
	id = strings.ToLower(strings.TrimSpace(id))
	assertValidID(id)
	if len(name) == 0 || len(name) > maxSkinName {
		panic("nsskin: a skin needs a name, of at most 40 characters")
	}
	if len(art) == 0 || len(art) > maxSkinArt {
		panic(ufmt.Sprintf("nsskin: art is %d bytes, the limit is %d", len(art), maxSkinArt))
	}
	// The SHAPE of the sprite is checked here; whether it renders is
	// nsview's business. Storing something the renderer will reject
	// silently is the failure mode this exists to prevent — a skin that
	// draws nothing, sold to somebody, discovered later.
	assertValidArt(art)
	if lock != "" {
		assertValidLabel(lock)
	}
	if artist == "" {
		panic("nsskin: a skin needs an artist to pay")
	}

	if v := skins.Get(id); v != nil {
		s := v.(*skin)
		if s.minted > 0 {
			panic(ufmt.Sprintf(
				"nsskin: %s has %d copies out — redefining it would change "+
					"what those holders bought; withdraw it instead", id, s.minted))
		}
		s.name, s.art, s.lock, s.artist = name, art, lock, artist
		return
	}
	skins.Set(id, &skin{name: name, art: art, lock: lock, artist: artist})
}

/*
Mint issues one copy of a definition to somebody.

The serial is the definition's own running count, so token ids read as
"ember#1", "ember#2". Never reused: the counter only goes up, even across
burns, because a reissued id would let a new token inherit whatever an
old one was pointed at.
*/
func Mint(cur realm, id string, to address) string {
	assertIsAdminOrShop(cur)
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and cannot be minted")
	}
	if to == "" {
		panic("nsskin: no recipient")
	}
	s.minted++
	tid := ufmt.Sprintf("%s#%d", id, s.minted)
	if err := nft.Mint(to, grc721.TokenID(tid)); err != nil {
		panic("nsskin: mint failed: " + err.Error())
	}
	tokenSkin.Set(tid, id)
	return tid
}

/*
Withdraw is the takedown control, and SKINS.md §6 makes it
non-negotiable: it has to exist before a single outside submission is
accepted, which means it has to exist now, while there is nothing to take
down and it is cheap to build.

Somebody will submit a character somebody else owns, or a bank's logo, or
something vile, and it will render inside other people's wallets with our
name beside it. When that happens the fix has to be one call, not a
migration.

It does NOT burn anything. The holder keeps the token; it simply stops
rendering, and every name pointing at it falls back to the ordinary card
at once. Burning somebody's property to solve our problem is a different
act with different consequences, and it is not this one.
*/
func Withdraw(cur realm, id string, withdrawn bool) {
	assertIsAdmin(cur)
	mustSkin(id).withdrawn = withdrawn
}

func SetTokenURIBase(cur realm, base string) {
	assertIsAdmin(cur)
	tokenURIBase = base
}

func SetAdmin(cur realm, a address) {
	assertIsAdmin(cur)
	if a == "" {
		panic("nsskin: refusing to leave the realm with no admin")
	}
	admin = a
}

func TrustShop(cur realm, a address, trusted bool) {
	assertIsAdmin(cur)
	if trusted {
		trustedShop.Set(a.String(), true)
		return
	}
	trustedShop.Remove(a.String())
}

// ---------------------------------------------------------------- grc721

func TransferFrom(cur realm, from, to address, tid grc721.TokenID) {
	if err := nft.TransferFrom(cur.Previous().Address(), from, to, tid); err != nil {
		panic("nsskin: " + err.Error())
	}
}

func Approve(cur realm, to address, tid grc721.TokenID) {
	if err := nft.Approve(cur.Previous().Address(), to, tid); err != nil {
		panic("nsskin: " + err.Error())
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	if err := nft.SetApprovalForAll(cur.Previous().Address(), operator, approved); err != nil {
		panic("nsskin: " + err.Error())
	}
}

// ---------------------------------------------------------------- checks

func mustSkin(id string) *skin {
	v := skins.Get(strings.ToLower(strings.TrimSpace(id)))
	if v == nil {
		panic("nsskin: no such skin: " + id)
	}
	return v.(*skin)
}

// An id goes into every token id and into the pointer a name stores, so
// it has to survive being split on "#" and compared byte for byte.
func assertValidID(id string) {
	if len(id) == 0 || len(id) > maxSkinID {
		panic("nsskin: a skin id must be 1 to 24 characters")
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' {
			continue
		}
		panic("nsskin: a skin id may only use a-z, 0-9 and -: " + id)
	}
}

func assertValidLabel(l string) {
	if len(l) == 0 || len(l) > 63 {
		panic("nsskin: a lock must be a domain label")
	}
	for i := 0; i < len(l); i++ {
		c := l[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' {
			continue
		}
		panic("nsskin: a lock may only use a-z, 0-9 and -: " + l)
	}
}

/*
assertValidArt mirrors the sprite checks nsview makes, and it is here for
one reason: nsview REJECTS THE WHOLE SPRITE SILENTLY. A malformed skin
does not draw a broken picture, it draws nothing at all, with no error
anywhere a person would see it.

Storing one would mean selling somebody a blank card and finding out
weeks later. So the shape is checked at the point of storage, where the
failure is a panic in a transaction nobody has paid for yet.

Deliberately checks the SHAPE and not the rendering. This realm does not
know how a card is composed and should not learn — that is the whole
reason the renderer is swappable.
*/
func assertValidArt(enc string) {
	parts := strings.Split(enc, "|")
	n := len(parts) - 1
	if n < 4 || n > 64 {
		panic(ufmt.Sprintf("nsskin: a sprite needs 4 to 64 rows, this has %d", n))
	}
	keys := map[string]bool{}
	for _, e := range strings.Split(parts[0], ",") {
		if len(e) != 8 || e[1] != '#' {
			panic("nsskin: a palette entry must be a letter, #, and six hex digits: " + e)
		}
		for i := 2; i < 8; i++ {
			c := e[i]
			if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
				continue
			}
			panic("nsskin: not a hex colour: " + e)
		}
		keys[e[:1]] = true
	}
	for y := 1; y <= n; y++ {
		if len(parts[y]) != n {
			panic(ufmt.Sprintf(
				"nsskin: row %d is %d wide but the sprite is %d rows tall — it must be square",
				y, len(parts[y]), n))
		}
		for x := 0; x < n; x++ {
			ch := parts[y][x : x+1]
			if ch == "." || keys[ch] {
				continue
			}
			panic(ufmt.Sprintf("nsskin: row %d uses colour %s, which the palette does not define", y, ch))
		}
	}
}
